// Üretilen dosya: tool/ozgun/uret.py. Matematik · Analitik geometri: doğru, çember, uzaklık (orta).
const ozMathematics11Orta = <(String, String, List<String>, String)>[
  ('P(a − 2, 5 − a) noktası II. bölgede bulunuyorsa a hangi aralıkta olmalıdır?', 'a < 2', ['2 < a < 5', 'a > 5', 'a < 5 ve a ≠ 2'], 'II. bölgede apsis negatif, ordinat pozitiftir: a − 2 < 0 ve 5 − a > 0. Buradan a < 2 ve a < 5 bulunur; ortak çözüm a < 2\'dir.'),
  ('a·b < 0 ve a < b olduğuna göre Q(a, b) noktası hangi bölgededir?', 'II. bölge', ['I. bölge', 'III. bölge', 'IV. bölge'], 'a·b < 0 olduğundan a ile b ters işaretlidir; a < b olduğu için a negatif, b pozitiftir. (−, +) işaretli nokta II. bölgededir.'),
  ('B(2k − 6, k + 1) noktası x ekseni üzerinde olduğuna göre bu noktanın orijine uzaklığı kaç birimdir?', '8', ['6', '4', '2√5'], 'x ekseni üzerinde ordinat sıfırdır: k + 1 = 0, k = −1. Apsis 2(−1) − 6 = −8 olur; orijine uzaklık |−8| = 8\'dir.'),
  ('Bir noktanın x eksenine uzaklığı 3, y eksenine uzaklığı 5 birimdir ve nokta III. bölgededir. Bu nokta hangisidir?', '(−5, −3)', ['(−3, −5)', '(5, −3)', '(−5, 3)'], 'y eksenine uzaklık |x| = 5, x eksenine uzaklık |y| = 3\'tür. III. bölgede iki koordinat da negatif olduğundan nokta (−5, −3)\'tür.'),
  ('Cebir ile geometriyi koordinatlar aracılığıyla birleştiren analitik geometrinin, Descartes ile aynı dönemde ve ondan bağımsız olarak geliştiren diğer kurucusu kimdir?', 'Pierre de Fermat', ['Gottfried Leibniz', 'Isaac Newton', 'Johannes Kepler'], 'Fermat, Descartes\'la aynı yıllarda koordinat yöntemini bağımsız olarak geliştirmiş; bu yüzden ikisi analitik geometrinin kurucuları sayılır.'),
  ('A(a, 3) ve B(1, −1) noktaları arasındaki uzaklık 5 birimdir. a\'nın alabileceği değerlerin toplamı kaçtır?', '2', ['4', '−2', '8'], '(a − 1)² + 16 = 25 olduğundan (a − 1)² = 9, a = 4 ya da a = −2\'dir. Toplam 2\'dir.'),
  ('P(t, 2t) noktasının orijine uzaklığı 3√5 birim ve P birinci bölgede ise t kaçtır?', '3', ['√5', '5', '9'], 'OP² = t² + 4t² = 5t² = 45 olduğundan t² = 9\'dur. Birinci bölgede t > 0 olduğu için t = 3 bulunur.'),
  ('Köşeleri A(0, 0), B(4, 0) ve C(2, 2√3) olan üçgen, kenar uzunluklarına göre hangi türdendir?', 'Eşkenar', ['Çeşitkenar', 'Dik ikizkenar', 'Geniş açılı'], '|AB| = 4, |AC| = √(4 + 12) = 4, |BC| = √(4 + 12) = 4\'tür. Üç kenar eşit olduğundan üçgen eşkenardır.'),
  ('A(2, 3), B(5, 7) ve C(x, 3) noktalarıyla oluşan üçgende |AB| = |BC| olduğuna göre x\'in A\'dan farklı değeri kaçtır?', '8', ['5', '7', '11'], '|AB| = 5\'tir. (x − 5)² + 16 = 25 olduğundan x − 5 = ±3, x = 8 ya da x = 2\'dir. x = 2 A noktasını verdiği için x = 8\'dir.'),
  ('Köşeleri A(0, 0), B(8, 0) ve C(0, 6) olan üçgenin üç köşesine eşit uzaklıktaki noktanın bu köşelere uzaklığı kaç birimdir?', '5', ['4', '3', '2√5'], 'Üçgen A köşesinde dik açılıdır. Dik üçgende üç köşeye eşit uzaklıktaki nokta hipotenüsün orta noktası (4, 3)\'tür; uzaklık hipotenüsün yarısı, yani 10/2 = 5\'tir.'),
  ('y = x doğrusu üzerinde olup A(3, 0) ve B(0, 5) noktalarına eşit uzaklıkta bulunan noktanın apsisi kaçtır?', '4', ['8/5', '2', '5/2'], 'P(t, t) için (t − 3)² + t² = t² + (t − 5)² yazılır. Sadeleşince (t − 3)² = (t − 5)², yani −6t + 9 = −10t + 25 ve t = 4 bulunur.'),
  ('Bir doğru parçasının bir ucu A(4, −2), orta noktası M(−1, 3) ise diğer ucunun koordinatları toplamı kaçtır?', '2', ['−2', '8', '4'], 'Diğer uç B = 2M − A = (−2 − 4, 6 + 2) = (−6, 8)\'dir. Koordinatların toplamı 2\'dir.'),
  ('Bir okulun bahçe planında kapı (−4, −3), çeşme (8, 5) noktasındadır. Kapıyla çeşmenin tam ortasına bir bank konacaktır. Bankın kapıya uzaklığı kaç birimdir?', '2√13', ['4√13', '√13', '2√26'], 'Bank (2, 1) noktasındadır. Kapıya uzaklığı √(36 + 16) = √52 = 2√13 birimdir; bu da toplam uzaklık 4√13\'ün yarısıdır.'),
  ('A(−3, 4) ve B(6, −2) noktalarını birleştiren doğru parçasını üç eş parçaya ayıran noktalardan A\'ya yakın olanı hangisidir?', '(0, 2)', ['(3, 0)', '(1, 2)', '(0, 1)'], 'A\'dan B\'ye yer değiştirme (9, −6)\'dır. Bunun üçte biri (3, −2) eklenirse (0, 2) bulunur.'),
  ('A(0, 0) ve B(10, 5) arasındaki doğru parçası üzerinde, A\'ya uzaklığı B\'ye uzaklığının 4 katı olan nokta hangisidir?', '(8, 4)', ['(2, 1)', '(6, 3)', '(4, 2)'], 'AP : PB = 4 : 1 olduğundan P = A + (4/5)(B − A) = (8, 4)\'tür.'),
  ('Bir ABC üçgeninin ağırlık merkezi G(3, 3)\'tür. A(−1, 4) ve B(5, 2) ise C köşesi hangisidir?', '(5, 3)', ['(3, 5)', '(4, 2)', '(7, 3)'], 'Ağırlık merkezi köşelerin ortalaması olduğundan C = 3G − A − B = (9 + 1 − 5, 9 − 4 − 2) = (5, 3) bulunur.'),
  ('Bir üçgenin köşeleri x ekseni üzerinde (−4, 0) ve (10, 0), üçüncü köşesi y ekseni üzerindedir. Ağırlık merkezi x ekseninin 3 birim üstünde ise üçüncü köşe hangisidir?', '(0, 9)', ['(0, 3)', '(0, 6)', '(0, 9/2)'], 'Ağırlık merkezinin ordinatı (0 + 0 + y)/3 = 3 olduğundan y = 9\'dur. Üçüncü köşe (0, 9)\'dur.'),
  ('ABCD paralelkenarının köşegenleri E(3, 2) noktasında kesişiyor. A(−1, 0) ve B(6, −1) ise D köşesi hangisidir?', '(0, 5)', ['(7, 4)', '(4, 3)', '(1, 6)'], 'Köşegenler birbirini ortaladığından C = 2E − A = (7, 4) ve D = 2E − B = (0, 5)\'tir.'),
  ('Bir paralelkenarda karşılıklı iki köşenin koordinatları toplamının, diğer iki karşılıklı köşenin koordinatları toplamına eşit olmasının nedeni nedir?', 'Köşegenlerin orta noktalarının aynı nokta olması', ['Karşılıklı kenarların dik olması', 'Komşu kenar uzunluklarının her zaman birbirine eşit olması', 'Köşegenlerin eşit uzunlukta olması'], 'Paralelkenarın köşegenleri birbirini ortalar. Ortak orta nokta için (A + C)/2 = (B + D)/2, yani A + C = B + D olur.'),
  ('Ayakkabı bağı formülü kullanılırsa uçları (2, 1), (6, 4) ve (1, 5) olan üçgensel bölge kaç birimkare yer kaplar?', '19/2', ['19', '17/2', '√2 + 9'], 'Ayakkabı bağı formülü: |2(4 − 5) + 6(5 − 1) + 1(1 − 4)| / 2 = |−2 + 24 − 3| / 2 = 19/2.'),
  ('Köşeleri A(−2, 3), B(4, −1) ve C(k, 3) olan üçgenin alanı 12 birimkare ve k > −2 ise k kaçtır?', '4', ['2', '6', '10'], 'AC kenarı y = 3 üzerinde ve uzunluğu |k + 2|\'dir; B\'nin bu doğruya uzaklığı 4\'tür. |k + 2| · 4 / 2 = 12\'den |k + 2| = 6, k > −2 için k = 4 bulunur.'),
  ('O(0, 0), A(x₁, y₁) ve B(x₂, y₂) köşeli üçgenin alanını veren ifade hangisidir?', '|x₁y₂ − x₂y₁| / 2', ['|x₁x₂ + y₁y₂| / 2', '|x₁y₁ − x₂y₂| / 2', '(x₁ + x₂)(y₁ + y₂) / 2'], 'Bir köşesi orijinde olan üçgenin alanı, diğer iki köşenin oluşturduğu determinantın mutlak değerinin yarısıdır: |x₁y₂ − x₂y₁| / 2.'),
  ('Köşeleri sırasıyla (0, 0), (5, 0), (5, 3) ve (2, 6) olan dörtgenin alanı kaç birimkaredir?', '19,5', ['21', '18', '22,5'], 'Ayakkabı bağı yöntemiyle çapraz çarpım farkları 0, 15, 24 ve 0\'dır. Toplam 39 olduğundan alan 39/2 = 19,5 birimkaredir.'),
  ('Ayakkabı bağı (Gauss alan) formülüyle bir çokgenin alanı hesaplanırken köşelerin hangi biçimde sıralanması gerekir?', 'Sınır boyunca ardışık, tek bir dönme yönünde', ['Apsislerine göre küçükten büyüğe, eşitlikte ordinatlarına göre', 'Orijine uzaklıklarına göre', 'Ordinatlarına göre büyükten küçüğe'], 'Formül, köşelerin sınır boyunca sırayla dolaşılmasını gerektirir. Rastgele sıralama kendini kesen bir çokgen tanımlar ve yanlış sonuç verir.'),
  ('Köşeleri (1, 1), (7, 1), (7, 5) ve (1, 5) olan dikdörtgenin içine, köşeleri bu dikdörtgenin kenar orta noktaları olan dörtgen çiziliyor. İç dörtgenin alanı kaç birimkaredir?', '12', ['24', '8', '16'], 'Dikdörtgenin alanı 6 · 4 = 24\'tür. Kenar orta noktalarını birleştiren dörtgenin alanı her zaman dış dörtgenin alanının yarısıdır: 12.'),
  ('Üç noktanın doğrusal olup olmadığını koordinatlarla test etmenin yollarından biri hangisidir?', 'Oluşan üçgenin alanının sıfır çıkması', ['Noktaların orijine uzaklıklarının eşit çıkması', 'Noktaların apsislerinin toplamının sıfır olması', 'Noktaların aynı bölgede bulunması'], 'Doğrusal üç nokta bir üçgen oluşturmaz; ayakkabı bağı formülüyle hesaplanan alan sıfır çıkar.'),
  ('Eğimi −√3 olan bir doğrunun eğim açısı kaç derecedir?', '120°', ['60°', '150°', '−120°'], 'tan α = −√3 ve 0° ≤ α < 180° koşulunu sağlayan açı 120°\'dir. Eğim açısı negatif alınmaz.'),
  ('Eğim açısı 150° olan bir doğrunun eğimi hangisidir?', '−√3/3', ['−√3', '√3/3', '−√3/2'], 'tan 150° = −tan 30° = −√3/3\'tür.'),
  ('Bir doğrunun eğimi hesaplanırken (y₂ − y₁)/(x₂ − x₁) yerine (y₁ − y₂)/(x₁ − x₂) kullanılırsa sonuç nasıl değişir?', 'Değişmez', ['İşaret değiştirir', 'Tersine döner', 'Mutlak değeri iki katına çıkar'], 'Pay ve paydanın ikisi de −1 ile çarpılmış olur; bu yüzden oran değişmez. Noktaların hangi sırayla alındığı önemsizdir.'),
  ('Bir yol levhasında %8 eğim yazmaktadır. Bu bilgi analitik geometri diliyle neyi anlatır?', 'Yatayda 100 m ilerleyince yükseklik 8 m değişir', ['Yolun yatayla 8 derecelik açı yapması', 'Yolda 100 m ilerleyince hızın %8 azalması', 'Yolun her 8 m\'lik yatay ilerlemede 100 m yükselmesi'], 'Yüzde eğim, eğimin 100 ile çarpılmasıdır. %8, düşey değişimin yatay değişime oranının 8/100 olduğunu gösterir.'),
  ('Eğimleri 2 ve −3 olan iki doğrudan hangisi daha diktir (y eksenine daha yakın bir doğrultudadır)?', 'Eğimi −3 olan', ['Eğimi 2 olan', 'İkisi eşit diktir', 'Bilgi yetersizdir'], 'Dikliği eğimin mutlak değeri belirler. |−3| > |2| olduğundan eğimi −3 olan doğru daha diktir; işaret yalnız yönü gösterir.'),
  ('Eğimi √3 olan bir doğru y ekseniyle kaç derecelik dar açı yapar?', '30°', ['60°', '45°', '90°'], 'Doğru x ekseniyle 60° yapar. Eksenler dik olduğundan y ekseniyle yaptığı dar açı 90° − 60° = 30°\'dir.'),
  ('A(2, 5), B(6, 7) ve C(10, 1) noktaları için AB ve BC doğrularının eğimlerinin çarpımı kaçtır?', '−3/4', ['−3/2', '3/4', '−1/12'], 'AB\'nin eğimi 2/4 = 1/2, BC\'nin eğimi −6/4 = −3/2\'dir. Çarpım −3/4\'tür.'),
  ('Eğim açısı α olan bir doğru için eğimin tan α\'ya eşit olmasının nedeni nedir?', 'Düşey değişimin yatay değişime oranı, α\'nın karşı dik kenarının komşu dik kenarına oranıdır', ['Doğru üzerindeki her parçanın uzunluğu α açısıyla doğru orantılıdır ve tan α kadar uzar', 'Doğrunun orijine uzaklığı sin α\'ya eşittir', 'Eğim, α açısının radyan ölçüsüne eşittir'], 'Doğru üzerinde iki nokta alınınca Δx ve Δy dik kenarlı bir üçgen oluşur. α\'ya göre karşı/komşu oranı tan α\'yı verir.'),
  ('Eğim açısı 0° ile 90° arasında değişen bir doğruda açı büyüdükçe eğim nasıl değişir?', 'Sınırsız olarak büyür', ['Önce artar sonra azalır', '1\'e yaklaşarak sabitlenir', 'Küçülür'], 'tan α, 0° ile 90° arasında artan bir fonksiyondur ve α 90°\'ye yaklaşırken sınırsız büyür.'),
  ('(−1, 4) ve (3, −4) noktalarından geçen doğrunun y eksenini kestiği noktanın ordinatı kaçtır?', '2', ['4', '−2', '6'], 'Eğim (−4 − 4)/(3 + 1) = −2\'dir. y − 4 = −2(x + 1) doğrusunda x = 0 alınırsa y = 2 bulunur.'),
  ('x eksenini 5\'te, y eksenini −3\'te kesen doğrunun denklemi hangisidir?', '3x − 5y = 15', ['5x − 3y = 15', '3x + 5y = 15', '5x + 3y = −15'], 'Eksen kesimli biçim x/5 + y/(−3) = 1\'dir. Her iki taraf 15 ile çarpılırsa 3x − 5y = 15 elde edilir.'),
  ('ax + by + c = 0 denkleminde b = 0 ve a ≠ 0 ise doğru nasıl konumlanır?', 'Düşey bir doğrudur', ['x eksenine paraleldir', 'Orijinden geçer', 'Eğimi 1\'dir'], 'b = 0 iken denklem x = −c/a olur. Bu, y eksenine paralel bir düşey doğrudur.'),
  ('Eksenleri pozitif ve eşit uzaklıklarda kesen ve (2, 3) noktasından geçen doğrunun denklemi hangisidir?', 'x + y = 5', ['x − y = −1', '2x + 3y = 13', 'x + y = 6'], 'Eksen kesimleri eşit olan doğru x/a + y/a = 1, yani x + y = a\'dır. (2, 3) yazılırsa a = 5 olur.'),
  ('Celsius (C) ve Fahrenheit (F) arasındaki ilişki doğrusaldır; su 0 °C\'de (32 °F) donar, 100 °C\'de (212 °F) kaynar. C yatay, F dikey eksen olacak şekilde çizilen doğrunun eğimi kaçtır?', '9/5', ['5/9', '32/100', '212/100'], 'Eğim (212 − 32)/(100 − 0) = 180/100 = 9/5\'tir. Bu nedenle F = (9/5)C + 32 yazılır.'),
  ('Eğim açısı 45° olan ve (3, 1) noktasından geçen doğru y eksenini nerede keser?', '(0, −2)', ['(0, 2)', '(0, 4)', '(0, −3)'], 'Eğim tan 45° = 1\'dir. y − 1 = x − 3, yani y = x − 2 olur; y eksenini (0, −2)\'de keser.'),
  ('A(1, −2) ve B(1, 6) noktalarından geçen doğrunun denklemi neden y = mx + n biçiminde yazılamaz?', 'Doğru düşeydir ve eğimi tanımsızdır', ['Doğru yataydır ve eğimi sıfırdır', 'Doğru orijinden geçmektedir', 'İki noktanın ordinatları farklı işaretlidir'], 'İki noktanın apsisleri eşittir; doğru x = 1 düşey doğrusudur. Düşey doğruların eğimi tanımsız olduğundan y = mx + n biçiminde yazılamazlar.'),
  ('Bir taksinin ücreti, açılış ücreti ve kilometre başına sabit ücretten oluşur. 4 km\'lik yolculuk 140 TL, 10 km\'lik yolculuk 260 TL tutmuştur. Mesafe–ücret doğrusunun ücret eksenini kestiği değer kaçtır?', '60 TL', ['20 TL', '35 TL', '100 TL'], 'Eğim (260 − 140)/(10 − 4) = 20 TL/km\'dir. 140 = 20 · 4 + n\'den açılış ücreti n = 60 TL bulunur.'),
  ('2x − 3y + 5 = 0 doğrusuyla aynı doğrultuda olup (1, 4) noktasını içeren doğru hangisidir?', '2x − 3y + 10 = 0', ['2x − 3y − 10 = 0', '3x + 2y − 11 = 0', '2x + 3y − 14 = 0'], 'Paralel doğru 2x − 3y + c = 0 biçimindedir. (1, 4) yazılırsa 2 − 12 + c = 0, c = 10 bulunur.'),
  ('3x + y = 7 doğrusunu dik açıyla kesen ve (2, −1) noktasını içeren doğrunun denklemi nedir?', 'x − 3y = 5', ['3x + y = 5', 'x + 3y = −1', 'x − 3y = −5'], 'Verilen doğrunun eğimi −3\'tür; dik doğrunun eğimi 1/3 olur. y + 1 = (x − 2)/3 düzenlenirse x − 3y = 5 bulunur.'),
  ('a₁x + b₁y + c₁ = 0 ve a₂x + b₂y + c₂ = 0 doğrularının paralel ve çakışmayan iki doğru olmasının koşulu hangisidir?', 'a₁/a₂ = b₁/b₂ ≠ c₁/c₂', ['a₁/a₂ = b₁/b₂ = c₁/c₂', 'a₁a₂ + b₁b₂ = 0', 'a₁/a₂ ≠ b₁/b₂'], 'x ve y katsayıları orantılıysa eğimler eşittir. Sabit terimler aynı oranda değilse doğrular ayrıktır, yani paraleldir.'),
  ('3x + ay = 2 ve 2x − 6y = 1 doğrularının dik kesişmesi için a kaç olmalıdır?', '1', ['−1', '9', '−4'], 'Diklik koşulu a₁a₂ + b₁b₂ = 0\'dır: 3 · 2 + a · (−6) = 0, a = 1.'),
  ('Eğimleri çarpımı −1 koşulu hangi dik doğru çiftine uygulanamaz?', 'Biri yatay, diğeri düşey olan çifte', ['Eğimleri 2 ve −1/2 olan çifte', 'Eğimleri 1 ve −1 olan çifte', 'Eğimleri 3 ve −1/3 olan çifte'], 'Düşey doğrunun eğimi tanımsız olduğundan çarpım hesaplanamaz. Yine de x = a ve y = b doğruları birbirine diktir.'),
  ('y = 2x + a ve y = −x + 6 doğruları x ekseni üzerinde kesişiyorsa a kaçtır?', '−12', ['12', '−6', '−3/2'], 'Kesişim x ekseninde ise y = 0\'dır. İkinci doğrudan x = 6 bulunur; 0 = 12 + a\'dan a = −12.'),
  ('x + y = 5, 2x − y = 1 ve kx + y = 7 doğruları aynı noktadan geçiyorsa k kaçtır?', '2', ['3', '1', '5/2'], 'İlk iki doğru (2, 3) noktasında kesişir. Üçüncü doğru da bu noktadan geçmeli: 2k + 3 = 7, k = 2.'),
  ('A(1, 2) ve B(4, 6) noktaları veriliyor. A\'dan geçen ve AB\'ye dik olan doğrunun denklemi hangisidir?', '3x + 4y = 11', ['4x − 3y = −2', '3x − 4y = −5', '4x + 3y = 10'], 'AB\'nin eğimi 4/3\'tür; dik doğrunun eğimi −3/4 olur. y − 2 = −(3/4)(x − 1) düzenlenirse 3x + 4y = 11 bulunur.'),
  ('Bir dikdörtgenin bir kenarı 2x − y + 4 = 0 doğrusu üzerindedir. Bu kenara komşu kenarlardan birinin üzerinde bulunduğu doğrunun eğimi kaçtır?', '−1/2', ['2', '1/2', '−2'], 'Dikdörtgenin komşu kenarları diktir. Verilen doğrunun eğimi 2 olduğundan komşu kenarın eğimi −1/2\'dir.'),
  ('ax − 2y = 4 ve 3x + by = 6 denklemleriyle verilen iki doğru çakışık ise a + b kaçtır?', '−1', ['1', '5', '−5/3'], 'Çakışıklık için a/3 = −2/b = 4/6 olmalıdır. Buradan a = 2 ve b = −3 bulunur; a + b = −1\'dir.'),
  ('kx + 3y = 5 doğrusu, eğimi 2 olan doğrulara dik ise k kaçtır?', '3/2', ['−6', '6', '−3/2'], 'kx + 3y = 5\'in eğimi −k/3\'tür. Diklik için (−k/3) · 2 = −1, k = 3/2.'),
  ('A(−2, 0), B(0, 4) ve C(6, 1) noktalarıyla oluşan üçgenin B köşesindeki açı kaç derecedir?', '90°', ['60°', '45°', '120°'], 'BA\'nın eğimi (0 − 4)/(−2 − 0) = 2, BC\'nin eğimi (1 − 4)/(6 − 0) = −1/2\'dir. Çarpım −1 olduğundan B\'deki açı diktir.'),
  ('2x + y = 8 ve x − 3y = −3 doğrularının kesişim noktasının orijine uzaklığı kaç birimdir?', '√13', ['5', '√5', '13'], 'Denklemler çözülünce (3, 2) bulunur. Orijine uzaklık √(9 + 4) = √13\'tür.'),
  ('k bir gerçek sayı olmak üzere x + 2y = 3k ve 2x − y = k doğrularının kesişim noktası k değiştikçe hangi doğru üzerinde hareket eder?', 'y = x', ['y = 2x', 'y = −x', 'y = x/2'], 'Sistem çözülünce x = k ve y = k bulunur. Kesişim noktası (k, k) olduğundan y = x doğrusu üzerindedir.'),
  ('x + y = 3 ve 2x − y = 0 doğrularının kesişim noktasından 3x + ay = 7 doğrusu da geçtiğine göre a kaçtır?', '2', ['1', '3', '4'], 'İlk iki doğru (1, 2) noktasında kesişir. 3 + 2a = 7 olduğundan a = 2\'dir.'),
  ('y = x + 1, y = −x + 5 doğruları ve x ekseni arasında kalan üçgenin alanı kaç birimkaredir?', '9', ['6', '12', '18'], 'Köşeler (−1, 0), (5, 0) ve (2, 3) noktalarıdır. Taban 6, yükseklik 3 olduğundan alan 6·3/2 = 9\'dur.'),
  ('2x + 3y = 6 ve kx − y = 4 doğrularının kesişim noktası x ekseni üzerinde olduğuna göre k kaçtır?', '4/3', ['3/4', '−4/3', '2/3'], '2x + 3y = 6 doğrusu x eksenini (3, 0) noktasında keser. Bu nokta kx − y = 4\'ü sağlamalıdır: 3k = 4, k = 4/3.'),
  ('y − 3 = m(x + 2) denklemiyle verilen doğru ailesinde (m gerçek sayı) aşağıdaki doğrulardan hangisi bulunmaz?', 'x = −2', ['y = 3', 'y = −3x/2', 'y = x + 5'], 'Aile (−2, 3) noktasından geçen ve eğimi tanımlı olan doğrulardır. x = −2 düşey olduğundan eğimi yoktur ve ailede yer almaz.'),
  ('Eğimleri 2 ve −1/2 olan iki doğru (1, 3) noktasında kesişiyor. Bu doğruların y eksenini kestiği noktalar arasındaki uzaklık kaç birimdir?', '5/2', ['3/2', '7/2', '2'], 'Doğrular y = 2x + 1 ve y = −x/2 + 7/2\'dir. y eksenini (0, 1) ve (0, 7/2)\'de keserler; uzaklık 5/2\'dir.'),
  ('x + y = 2, 2x − y = 1 ve kx + 2y = 5 doğruları tek bir noktada kesişiyorsa k kaçtır?', '3', ['2', '4', '1'], 'İlk ikisi (1, 1)\'de kesişir. k + 2 = 5 olduğundan k = 3\'tür.'),
  ('3x − 4y + k = 0 doğrusunun orijine uzaklığı 2 birim ise k\'nın alabileceği değerlerin çarpımı kaçtır?', '−100', ['100', '−10', '−25'], '|k| / 5 = 2 olduğundan k = ±10\'dur. Çarpım −100\'dür.'),
  ('ax₀ + by₀ + c ifadesinin işareti, (x₀, y₀) noktası ve ax + by + c = 0 doğrusu için neyi belirtir?', 'Noktanın doğrunun hangi tarafında olduğunu', ['Noktanın doğruya uzaklığını', 'Doğrunun eğiminin işaretini', 'Noktanın orijine yakın olup olmadığını'], 'İfade doğrunun iki yarı düzleminde zıt işaret alır. Uzaklık için mutlak değer alınır, işaret ise tarafı gösterir.'),
  ('A(1, 2), B(4, 6) ve C(7, 2) köşeli ABC üçgeninin alanını, C noktasının AB doğrusuna uzaklığından yararlanarak bulunuz.', '12', ['24', '10', '6'], 'AB doğrusu 4x − 3y + 2 = 0 ve |AB| = 5\'tir. C\'nin uzaklığı |28 − 6 + 2|/5 = 24/5. Alan = 5·(24/5)/2 = 12.'),
  ('a pozitif bir gerçek sayı olmak üzere P(a, 0) noktasının 4x − 3y + 8 = 0 doğrusuna uzaklığı 4 birim ise a kaçtır?', '3', ['7', '5', '12'], '|4a + 8|/5 = 4 olduğundan 4a + 8 = ±20 ve a = 3 ya da a = −7. Pozitif olan değer 3\'tür.'),
  ('Q(a, 4) noktasının y = x doğrusuna uzaklığı 2√2 birimdir. a\'nın alabileceği değerlerin toplamı kaçtır?', '8', ['4', '0', '16'], 'y = x doğrusu x − y = 0 biçimindedir. |a − 4|/√2 = 2√2 ise |a − 4| = 4 olur; a = 0 ya da 8, toplam 8.'),
  ('Katsayıları farklı yazılmış 6x + 8y + 7 = 0 ile 3x + 4y − 2 = 0 doğrularının birbirine olan uzaklığı nedir?', '11/10', ['9/10', '1/2', '9/5'], 'İkinci doğru 6x + 8y − 4 = 0 biçiminde yazılır. Uzaklık |7 − (−4)| / √(36 + 64) = 11/10\'dur.'),
  ('x − 2y + 3 = 0 doğrusuna paralel ve ondan √5 birim uzaklıkta olan doğrulardan biri aşağıdakilerden hangisidir?', 'x − 2y + 8 = 0', ['x − 2y + 6 = 0', '2x − y + 8 = 0', 'x − 2y + 13 = 0'], 'x − 2y + c = 0 için |c − 3|/√5 = √5 olmalıdır; c = 8 ya da c = −2. Seçeneklerden yalnız c = 8 uygundur.'),
  ('3x − 4y + 1 = 0 ve 3x − 4y − 9 = 0 doğrularına eşit uzaklıkta bulunan paralel doğrunun denklemi hangisidir?', '3x − 4y − 4 = 0', ['3x − 4y − 5 = 0', '3x − 4y + 4 = 0', '3x − 4y − 8 = 0'], 'Orta paralelin sabit terimi (1 + (−9))/2 = −4 olur. Denklem 3x − 4y − 4 = 0\'dır.'),
  ('x + y − 2 = 0 ve x − y = 0 doğrularının açıortay doğruları hangisidir?', 'x = 1 ve y = 1', ['x = 2 ve y = 2', 'y = x ve y = −x', 'x = 1 ve y = 2'], 'Her iki denklemin √2 ile bölünmesi aynıdır. (x + y − 2) = ±(x − y) eşitliğinden y = 1 ve x = 1 bulunur.'),
  ('4x + 3y − 12 = 0 doğrusunun koordinat eksenleriyle oluşturduğu üçgenin iç teğet çemberinin yarıçapı kaç birimdir?', '1', ['2', '3/2', '6/5'], 'Üçgenin dik kenarları 3 ve 4, hipotenüsü 5\'tir. r = (3 + 4 − 5)/2 = 1 olur.'),
  ('y = 3x ve y = −2x doğruları arasındaki dar açı kaç derecedir?', '45°', ['30°', '60°', '90°'], 'tan θ = |(−2 − 3)/(1 + 3·(−2))| = |−5/−5| = 1 olduğundan θ = 45°\'dir.'),
  ('Orijinden geçen x + y = 0 ve √3x − y = 0 doğrularının oluşturduğu dar açının ölçüsü nedir?', '75°', ['45°', '60°', '105°'], 'Eğim açıları 135° ve 60°\'dir. Aradaki açı 135° − 60° = 75° bulunur.'),
  ('A(3, 4) noktasının y = x doğrusuna göre simetriği A\', x eksenine göre simetriği A\'\' ise |A\'A\'\'| kaç birimdir?', '5√2', ['5', '7', '√50 − 1'], 'A\'(4, 3) ve A\'\'(3, −4) bulunur. Uzaklık √(1 + 49) = √50 = 5√2\'dir.'),
  ('Bir noktayı önce y = x doğrusuna, sonra y = −x doğrusuna göre simetrisini alan dönüşümlerin bileşkesi hangi dönüşüme eşittir?', 'Orijine göre simetriye', ['x eksenine göre simetriye', 'y eksenine göre simetriye', '90° dönmeye'], '(a, b) → (b, a) → (−a, −b) olur. Bu, orijine göre simetriden başka bir şey değildir.'),
  ('A(1, 2) noktasının simetriği A\'(5, −2) ise simetri doğrusunun denklemi hangisidir?', 'y = x − 3', ['y = x + 3', 'y = −x + 3', 'y = x − 1'], 'AA\' eğimi −1 olduğundan simetri doğrusunun eğimi 1\'dir ve orta noktadan (3, 0) geçer: y = x − 3.'),
  ('Ters fonksiyon grafiği mantığıyla, y = 2x + 1 doğrusunun y = x aynasındaki görüntüsünün denklemi nedir?', 'x − 2y − 1 = 0', ['2x − y + 1 = 0', 'x + 2y − 1 = 0', '2x − y − 1 = 0'], 'x ile y yer değiştirir: x = 2y + 1. Bu, x − 2y − 1 = 0 biçiminde yazılır.'),
  ('y = 3x − 2 doğrusu 2 birim sağa ve 1 birim yukarı ötelendiğinde elde edilen doğrunun y eksenini kestiği nokta hangisidir?', '(0, −7)', ['(0, −3)', '(0, −1)', '(0, 5)'], 'Yeni doğru: y − 1 = 3(x − 2) − 2, yani y = 3x − 7. y eksenini (0, −7)\'de keser.'),
  ('|x| + |y| ≤ 3 eşitsizliğinin belirttiği bölgenin alanı kaç birimkaredir?', '18', ['9', '12', '36'], 'Bölge köşeleri (±3, 0) ve (0, ±3) olan bir karedir; köşegenleri 6\'dır. Alan 6·6/2 = 18\'dir.'),
  ('|x| ≤ 2 ve |y| ≤ 3 eşitsizliklerinin belirttiği dikdörtgen bölgede (kenarlar dahil) kaç tane tam sayı koordinatlı nokta vardır?', '35', ['24', '20', '12'], 'x için −2\'den 2\'ye 5, y için −3\'ten 3\'e 7 değer vardır. Toplam 5·7 = 35 noktadır.'),
  ('Bir parselin sınırları x ≥ 1, y ≥ 1 ve x + y ≤ 6 koşullarıyla tanımlanıyor (birim: dam). Parselin alanı kaç damkaredir?', '8', ['10', '16', '4'], 'Köşeler (1, 1), (5, 1) ve (1, 5) noktalarıdır. Dik kenarlar 4 olduğundan alan 4·4/2 = 8\'dir.'),
  ('y = |x| grafiğinin üstünde, y = 4 doğrusunun altında kalan kapalı bölgenin ölçüsü kaç birimkaredir?', '16', ['8', '32', '12'], 'Bölge köşeleri (0, 0), (−4, 4) ve (4, 4) olan bir üçgendir. Taban 8, yükseklik 4 olduğundan alan 16\'dır.'),
  ('x ≥ |y| eşitsizliğinin belirttiği bölge için hangisi doğrudur?', 'Pozitif x eksenini içine alan 90° açılı bir bölgedir', ['İkinci ve üçüncü bölgeyi kapsar', 'Alanı sonlu bir üçgendir', 'y eksenini kesen bir şerittir'], 'x ≥ y ve x ≥ −y olmalıdır. Bu, y = x ve y = −x doğruları arasında kalan, sağa açılan 90°\'lik kamadır.'),
  ('y = 2x + 4 ve y = −x + 4 doğrularının kesişim noktası ile bu doğruların x eksenini kestiği iki nokta bir üçgen oluşturur. Bu üçgenin ölçüsü nedir?', '12', ['8', '16', '6'], 'Köşeler (−2, 0), (4, 0) ve (0, 4) noktalarıdır. Taban 6, yükseklik 4 olduğundan alan 12\'dir.'),
  ('x + y = 6 doğrusu, x = 0, y = 0 ve x = 2 doğrularının sınırladığı yamuğun alanı kaç birimkaredir?', '10', ['12', '8', '9'], 'Paralel kenarlar x = 0\'da 6, x = 2\'de 4 uzunluğundadır. Yükseklik 2 olduğundan alan (6 + 4)·2/2 = 10\'dur.'),
  ('m < 0 olmak üzere y = mx + 6 doğrusu ile koordinat eksenlerinin sınırladığı üçgenin alanı 9 birimkare ise m kaçtır?', '−2', ['2', '−1/2', '−3'], 'x eksenini −6/m\'de keser. Alan 6·(6/|m|)/2 = 18/|m| = 9 ise |m| = 2 ve m negatif olduğundan m = −2.'),
  ('O(0, 0), B(8, 0) ve C(0, 4) köşeli üçgenin alanını iki eşit parçaya bölen ve orijinden geçen y = mx doğrusunda m kaçtır?', '1/2', ['1/4', '2', '1'], 'Alanı yarıya bölen, O köşesinden geçen doğru kenarortaydır. BC\'nin orta noktası (4, 2) olduğundan m = 2/4 = 1/2\'dir.'),
  ('A(3, 1) ve B(1, 5) noktalarından eşit uzaklıkta bulunan y ekseni üzerindeki noktanın ordinatı kaçtır?', '2', ['3', '1', '5/2'], '(0, b) için 9 + (b − 1)² = 1 + (b − 5)² olur. Düzenlenirse 8b = 16 ve b = 2 bulunur.'),
  ('A(1, 1), B(3, 5) ve C(7, 3) köşeli üçgende A köşesinden BC kenarına çizilen yüksekliğin denklemi hangisidir?', 'y = 2x − 1', ['y = −2x + 3', 'y = x/2 + 1/2', 'y = 2x + 1'], 'BC eğimi (3 − 5)/(7 − 3) = −1/2\'dir. Yüksekliğin eğimi 2 olur: y − 1 = 2(x − 1), yani y = 2x − 1.'),
  ('O(0, 0) ile A(12, 18) noktalarını birleştiren doğru parçası üzerinde uç noktalar dahil kaç tane tam sayı koordinatlı nokta bulunur?', '7', ['6', '13', '30'], 'EBOB(12, 18) = 6\'dır. Parça üzerinde 6 + 1 = 7 kafes noktası vardır.'),
  ('A(2, 3) ve B(10, 15) noktaları arasındaki doğru parçasının üzerinde, uç noktalar hariç kaç kafes noktası vardır?', '3', ['4', '11', '2'], 'Koordinat farkları 8 ve 12\'dir; EBOB 4\'tür. Uçlar hariç 4 − 1 = 3 kafes noktası bulunur.'),
  ('A(0, 0) ve B(7, 5) noktalarını birleştiren doğru parçası için hangisi doğrudur?', 'Uç noktalar dışında hiç kafes noktası içermez', ['Tam olarak bir kafes noktası içerir', 'Tam olarak beş kafes noktası içerir', 'Tam olarak yedi kafes noktası içerir'], 'Koordinat farklarının EBOB\'u 1\'dir. Bu durumda doğru parçası üzerinde uç noktalardan başka kafes noktası yoktur.'),
  ('|x| + |y| = 6 denklemini sağlayan kaç tane tam sayı koordinatlı nokta vardır?', '24', ['12', '36', '18'], 'Nokta orijine Manhattan uzaklığı 6 olan karenin üzerindedir. Çevresinde 4·6 = 24 kafes noktası bulunur.'),
  ('Manhattan uzaklığında merkeze eşit uzaklıktaki noktaların oluşturduğu \'çember\' hangi şekildir?', 'Köşegenleri eksenler üzerinde olan bir kare', ['Kenarları eksenlere paralel bir kare', 'Merkezli bir daire', 'Köşeleri eksenlerde olan bir eşkenar üçgen'], '|x| + |y| = r denklemi (±r, 0) ve (0, ±r) köşeli, köşegenleri eksenler üzerinde olan bir kare belirtir.'),
  ('İki nokta arasındaki Manhattan uzaklığı ile Öklid uzaklığı karşılaştırılırsa hangisi her zaman doğrudur?', 'Manhattan uzaklığı, Öklid uzaklığından küçük olamaz', ['Manhattan uzaklığı, Öklid uzaklığından büyük olamaz', 'İki uzaklık daima eşittir', 'Manhattan uzaklığı daima Öklid uzaklığının iki katıdır'], '|a| + |b| ≥ √(a² + b²) eşitsizliği her gerçek a, b için geçerlidir. Eşitlik yalnız noktalar aynı eksene paralel doğru üzerindeyken sağlanır.'),
  ('x = 1 + 2t ve y = 3 − t doğrusunun x eksenini kestiği nokta hangisidir?', '(7, 0)', ['(3, 0)', '(5, 0)', '(0, 3)'], 'x eksenindeyken y = 0, yani t = 3 olur. x = 1 + 6 = 7 bulunur.'),
  ('A(0, 0), B(3, 1) ve P(t) = A + t(B − A) olsun. t = 2 için P noktası AB doğrusunun neresindedir?', 'B noktasının ötesinde, |AP| = 2|AB| olacak biçimde', ['A ile B arasında, orta noktada', 'A noktasının ötesinde, B\'nin tersi yönde', 'B noktası ile çakışık'], 'P(2) = (6, 2) olur. t > 1 olduğundan nokta B\'nin ötesindedir ve A\'ya uzaklığı |AB|\'nin iki katıdır.'),
  ('3x − 2y + 5 = 0 doğrusunun doğrultu vektörü aşağıdakilerden hangisidir?', '(2, 3)', ['(3, −2)', '(3, 2)', '(−3, −2)'], 'Doğrunun normal vektörü (3, −2)\'dir. Buna dik olan (2, 3) vektörü doğrunun yönünü gösterir.'),
  ('Doğrultu vektörü (−1, 4) olan ve (2, 1) noktasından geçen doğrunun denklemi hangisidir?', '4x + y − 9 = 0', ['4x − y − 7 = 0', 'x + 4y − 6 = 0', 'x − 4y + 2 = 0'], 'Eğim 4/(−1) = −4\'tür. y − 1 = −4(x − 2) yazılırsa 4x + y − 9 = 0 elde edilir.'),
  ('(x − 2)² + (y + 3)² = 25 çemberinin x eksenini kestiği iki nokta arasındaki uzaklık kaç birimdir?', '8', ['10', '6', '4√6'], 'y = 0 için (x − 2)² = 16, x = −2 ya da 6\'dır. Noktalar arasındaki uzaklık 8\'dir.'),
  ('(x − 3)² + (y + 2)² = 25 çemberinin y eksenini kestiği noktaların ordinatlarının çarpımı kaçtır?', '−12', ['12', '−16', '−6'], 'x = 0 için 9 + (y + 2)² = 25 olur, y = 2 ya da y = −6\'dır. Çarpım −12\'dir.'),
  ('x = 2 + 3cosθ ve y = −1 + 3sinθ parametrik denklemleri hangi geometrik şekli gösterir?', 'Merkezi (2, −1), yarıçapı 3 olan çemberi', ['Merkezi (−2, 1), yarıçapı 3 olan çemberi', 'Merkezi (2, −1), yarıçapı 9 olan çemberi', 'Eksenleri 2 ve 3 olan elipsi'], '(x − 2)² + (y + 1)² = 9 elde edilir. Bu, merkezi (2, −1) ve yarıçapı 3 olan çemberdir.'),
  ('y = √(25 − x²) denklemiyle verilen eğri hangi şekildir?', 'Merkezi orijin olan çemberin üst yarısı', ['Merkezi orijin olan çemberin sağ yarısı', 'Merkezi orijin olan tam çember', 'Köşeleri eksenlerde olan bir parabol'], 'Kare alınınca x² + y² = 25 elde edilir; fakat kök y ≥ 0\'ı gerektirdiğinden yalnız üst yarı çember kalır.'),
  ('x² + y² + 4x − 2y + k = 0 denkleminin bir çember belirtmesi için k hangi koşulu sağlamalıdır?', 'k < 5', ['k > 5', 'k ≤ 5', 'k > −5'], '(x + 2)² + (y − 1)² = 5 − k olur. Çember için 5 − k > 0, yani k < 5 olmalıdır.'),
  ('x² + y² − 2x + 6y + 10 = 0 denkleminin grafiği için hangisi doğrudur?', 'Tek bir nokta belirtir', ['Yarıçapı 1 olan bir çember belirtir', 'Hiçbir nokta belirtmez', 'Yarıçapı 10 olan bir çember belirtir'], '(x − 1)² + (y + 3)² = 1 + 9 − 10 = 0 olur. Denklemi yalnız (1, −3) noktası sağlar.'),
  ('x² + y² + 2ax + 2by + c = 0 denkleminin çember belirtmesi için gerekli ve yeterli koşul hangisidir?', 'a² + b² > c', ['a² + b² < c', 'a + b > c', 'a² + b² = c²'], 'Kareye tamamlanınca (x + a)² + (y + b)² = a² + b² − c olur. Yarıçap karesi pozitif olmalıdır.'),
  ('Her iki koordinat eksenine de teğet olan çemberlerin merkezleri hangi doğrular üzerinde bulunur?', 'y = x ve y = −x doğruları', ['Yalnız y = x doğrusu', 'x = 0 ve y = 0 doğruları', 'y = 2x ve y = −2x doğruları'], 'Eksenlere teğet çemberde |a| = |b| = r olur. Merkezin (a, b) koordinatı y = x ya da y = −x doğrusu üzerindedir.'),
  ('x² + y² − 6x − 8y + 9 = 0 çemberi hangi eksene teğettir?', 'Yalnız x eksenine', ['Yalnız y eksenine', 'Hem x hem y eksenine', 'Hiçbir eksene'], '(x − 3)² + (y − 4)² = 16\'dır. r = 4 merkezin ordinatına eşit, apsisi 3\'e eşit değildir; çember yalnız x eksenine teğettir.'),
  ('x² + y² + 10x − 6y + 9 = 0 çemberinin y eksenine değme noktası hangisidir?', '(0, 3)', ['(0, −3)', '(−5, 0)', '(0, 5)'], '(x + 5)² + (y − 3)² = 25 olur. Merkezin apsisinin mutlak değeri r = 5\'e eşittir; değme noktası merkezle aynı ordinatlıdır: (0, 3).'),
  ('(x − 1)² + (y − 4)² = r² çemberinin x eksenini iki farklı noktada kesmesi için r hangi koşulu sağlamalıdır?', 'r > 4', ['r > 1', 'r < 4', 'r = 4'], 'Merkezin x eksenine uzaklığı 4\'tür. Çemberin ekseni iki noktada kesmesi için r > 4 olmalıdır.'),
  ('Merkezi (2, 5) olan çember y eksenini iki noktada kesiyor, x eksenini kesmiyor. Yarıçap hangi aralıktadır?', '2 < r < 5', ['r > 5', 'r < 2', '5 < r < 7'], 'y eksenini kesmesi için r > 2, x eksenini kesmemesi için r < 5 gerekir.'),
  ('O(0, 0), B(4, 0) ve C(0, 2) noktalarından geçen çemberin yarıçapı kaç birimdir?', '√5', ['5/2', '2√2', '3'], 'x² + y² + Dx + Ey = 0 için D = −4, E = −2 bulunur. Merkez (2, 1), r = √(4 + 1) = √5\'tir.'),
  ('ABC üçgeninin köşeleri A(1, 1), B(1, 5) ve C(5, 5) noktalarıdır. Bu üçgenin çevrel çemberinin yarıçapı kaçtır?', '2√2', ['4', '√8 + 1', '2√3'], 'B\'deki açı diktir, AC çaptır. |AC| = √(16 + 16) = 4√2 olduğundan yarıçap 2√2\'dir.'),
  ('Bir çember x ekseni üzerindeki A(−1, 0) ve B(7, 0) noktalarını ve ayrıca C(3, 4) noktasını içeriyor. Bu çemberin denklemini yazınız.', '(x − 3)² + y² = 16', ['(x − 3)² + y² = 4', '(x − 3)² + (y − 4)² = 16', '(x − 3)² + y² = 32'], 'Merkez (3, 0) alınırsa A, B ve C\'ye uzaklık 4 olur. Denklem (x − 3)² + y² = 16\'dır.'),
  ('Orijinden geçen, x eksenini 6 noktasında ve y eksenini 8 noktasında kesen çemberin genel denklemi hangisidir?', 'x² + y² − 6x − 8y = 0', ['x² + y² + 6x + 8y = 0', 'x² + y² − 6x − 8y − 25 = 0', 'x² + y² − 3x − 4y = 0'], 'F = 0 olduğu için orijin üzerindedir. B ve C yerine yazılınca D = −6, E = −8 bulunur.'),
  ('P(5, 4) noktası x² + y² − 4x − 6y − 3 = 0 çemberine göre nerede bulunur?', 'Çemberin içinde', ['Çemberin üzerinde', 'Çemberin dışında', 'Çemberin merkezindedir'], 'Nokta yerine yazılırsa 25 + 16 − 20 − 24 − 3 = −6 < 0 bulunur. Negatif değer noktanın çemberin içinde olduğunu gösterir.'),
  ('x² + y² − 2x + 4y − 11 = 0 çemberine P(5, 2) noktasından çizilen teğet parçasının uzunluğu kaç birimdir?', '4', ['16', '√11', '2√3'], 'Noktanın çembere göre kuvveti 25 + 4 − 10 + 8 − 11 = 16\'dır. Teğet uzunluğu bunun karekökü olan 4\'tür.'),
  ('Merkezi orijin ve yarıçapı 5 olan çember için P(6, 8) noktasının çembere en yakın ve en uzak uzaklıklarının çarpımı kaçtır?', '75', ['50', '60', '100'], '|OP| = 10\'dur. En yakın uzaklık 10 − 5 = 5, en uzak uzaklık 10 + 5 = 15; çarpım 75\'tir.'),
  ('y = x + k doğrusunun x² + y² = 8 çemberine teğet olabilmesi için k\'nın alabileceği değerlerin çarpımı kaçtır?', '−16', ['16', '−8', '4'], 'Merkezden doğruya uzaklık |k|/√2 = 2√2 olmalıdır; k = ±4. Çarpım −16\'dır.'),
  ('y = 2x + k doğrusunun x² + y² = 5 çemberini iki farklı noktada kesmesi için k hangi aralıkta olmalıdır?', '−5 < k < 5', ['k > 5', 'k < −5 veya k > 5', '−√5 < k < √5'], 'Merkezin doğruya uzaklığı |k|/√5 < √5 olmalıdır; bu |k| < 5 demektir.'),
  ('Merkezi (1, −2) olan ve (3, 1) noktasından geçen çembere bu noktada çizilen teğet hangi denklemle ifade edilir?', '2x + 3y − 9 = 0', ['3x + 2y − 11 = 0', '2x − 3y − 3 = 0', '3x − 2y − 7 = 0'], 'Merkez (1, −2) ile (3, 1) arasındaki yarıçap vektörü (2, 3)\'tür. Teğet buna diktir: 2(x − 3) + 3(y − 1) = 0, yani 2x + 3y − 9 = 0.'),
  ('x² + y² = 18 çemberine eğimi 1 olan teğetlerden biri aşağıdakilerden hangisidir?', 'y = x + 6', ['y = x + 3', 'y = x + 18', 'y = x + 9'], 'y = x + k için |k|/√2 = 3√2, |k| = 6 olur. Seçeneklerden yalnız y = x + 6 uygundur.'),
  ('Bir çemberin teğeti ile teğetin değme noktasından geçen yarıçap arasındaki ilişki, analitik geometride hangi işlemle kullanılır?', 'Teğetin eğimi ile yarıçapın eğiminin çarpımının −1 olması', ['Teğetin eğimi ile yarıçapın eğiminin eşit olması', 'Teğet ve yarıçapın aynı noktadan geçen iki kenarortay olması', 'Teğetin uzunluğunun yarıçapa eşit olması'], 'Teğet ile yarıçap diktir. Eğimleri varsa çarpımları −1 olur; eksenlere paralel durumlarda bu ilişki ayrıca düşünülür.'),
  ('4x + 3y − 25 = 0 doğrusu (x − 1)² + (y − 2)² = 25 çemberini iki noktada kesiyor. Oluşan kirişin uzunluğu kaçtır?', '8', ['6', '10', '2√34'], 'Merkezin doğruya uzaklığı |4 + 6 − 25|/5 = 3\'tür. Kiriş uzunluğu 2√(25 − 9) = 8\'dir.'),
  ('x² + y² = 25 çemberinin içindeki P(0, 3) noktasından geçen kirişlerin en kısasının uzunluğu kaç birimdir?', '8', ['10', '6', '4√5'], 'En kısa kiriş OP\'ye dik olandır. Merkeze uzaklık 3 olduğundan uzunluk 2√(25 − 9) = 8\'dir.'),
  ('y = x + k doğrusunun x² + y² = 4 çemberinden ayırdığı kirişin uzunluğu 2√2 ise k\'nın pozitif değeri kaçtır?', '2', ['4', '√2', '2√2'], 'Yarım kiriş √2 olduğundan merkez uzaklığı √(4 − 2) = √2\'dir. |k|/√2 = √2 ise |k| = 2 olur.'),
  ('(x − 2)² + (y − 1)² = 20 çemberinin içindeki M(3, 3) noktası bir kirişin orta noktasıdır. Bu kirişin uzunluğu kaç birimdir?', '2√15', ['√15', '10', '4√5'], 'Merkezle M arasındaki uzaklık √5\'tir. Kiriş uzunluğu 2√(20 − 5) = 2√15\'tir.'),
  ('Merkezleri (0, 0) ve (6, 0), yarıçapları sırasıyla 2 ve 3 olan çemberlere birden kaç farklı doğru teğet olabilir?', '4', ['3', '2', '1'], 'Merkezler arası uzaklık 6, yarıçaplar toplamı 5\'ten büyüktür. Çemberler ayrıktır ve 4 ortak teğet vardır.'),
  ('Merkezi (1, 0) ve yarıçapı 2 olan çember, x² + y² = 25 çemberinin içinde kalıyor. İkisine birden teğet olan kaç doğru çizilebilir?', '0', ['1', '2', '4'], 'Merkezler arası uzaklık 1, yarıçap farkı 3\'ten küçüktür. Küçük çember büyüğün içinde kalır ve ortak teğet yoktur.'),
  ('x² + y² − 2x − 4y − 4 = 0 ile x² + y² − 2x − 4y + 1 = 0 denklemleri arasındaki ilişki nasıl yorumlanır?', 'Eş merkezlidir ve ortak noktaları yoktur', ['Dıştan teğettir', 'İki noktada kesişir', 'İçten teğettir'], 'İkisinin de merkezi (1, 2)\'dir; yarıçap kareleri 9 ve 4\'tür. Eş merkezli çemberlerin ortak noktası olmaz.'),
  ('Merkezi orijinde ve yarıçapı 2 olan çember, merkezi (3, 4) olan r yarıçaplı çemberin içinde ve ona değecek şekilde duruyorsa r kaçtır?', '7', ['3', '5', '9'], 'Merkezler arası uzaklık 5\'tir. İçten teğette 5 = r − 2 olur, yani r = 7\'dir.'),
  ('x² + y² = 16 ve x² + y² − 8x = 0 çemberlerinin kesiştiği iki nokta birbirinden kaç birim uzaktadır?', '4√3', ['2√3', '8', '6'], 'Denklemler çıkarılırsa 8x = 16, x = 2 bulunur. Kiriş uzunluğu 2√(16 − 4) = 4√3\'tür.'),
  ('Merkezleri (3, 0) ve (0, 3) olan, yarıçapları 3 birim ve ikisi de orijinden geçen çemberlerin diğer kesişim noktası orijine kaç birim uzaktadır?', '3√2', ['6', '3', '√18 + 3'], 'Çıkarma işlemi y = x doğrusunu verir. Ortak noktalar (0, 0) ve (3, 3)\'tür; uzaklık 3√2\'dir.'),
  ('Birbirine teğet iki çemberin denklemleri taraf tarafa çıkarılırsa elde edilen doğru neye karşılık gelir?', 'Değme noktasındaki ortak teğete', ['Merkezleri birleştiren doğruya', 'Yarıçapların ortak uzantısına', 'Ortak dış teğetlerden birine'], 'Çemberlerin tek ortak noktası olduğundan kuvvet ekseni o noktadan geçen ortak teğettir.'),
  ('Kuvvet ekseni üzerindeki bir noktadan iki çembere çizilen teğet parçaları için hangisi doğrudur?', 'Uzunlukları eşittir', ['Uzunlukları yarıçaplarla orantılıdır', 'Biri her zaman diğerinin iki katıdır', 'Birbirine diktir'], 'Kuvvet ekseni, iki çembere göre kuvvetleri eşit olan noktaların kümesidir. Teğet uzunluğunun karesi kuvvete eşittir.'),
  ('A(1, 2) ve B(5, 4) noktalarına eşit uzaklıktaki noktaların geometrik yeri hangi doğrudur?', '2x + y = 9', ['x + 2y = 9', '2x − y = −3', 'x − 2y = −3'], 'Orta nokta (3, 3), AB eğimi 1/2\'dir. Orta dikmenin eğimi −2 olur: y − 3 = −2(x − 3), yani 2x + y = 9.'),
  ('A ve B sabit noktalar, k pozitif ve k ≠ 1 olmak üzere |PA|/|PB| = k koşulunu sağlayan P noktalarının geometrik yeri nedir?', 'Bir çemberdir', ['AB doğru parçasının orta dikmesidir', 'Odak noktası A olan bir parabol', 'AB doğrusunun kendisinin uzantısıdır'], 'k = 1 iken orta dikme elde edilir. k ≠ 1 için uzaklıkların oranının sabit olduğu noktalar Apollonius çemberini oluşturur.'),
  ('A(0, 0) ve B(6, 0) sabit noktalar, C noktası y = 6 doğrusu üzerinde değişiyor. ABC üçgeninin ağırlık merkezi hangi doğru üzerinde hareket eder?', 'y = 2', ['y = 3', 'y = 4/3', 'x = 2'], 'Ağırlık merkezinin ordinatı (0 + 0 + 6)/3 = 2\'dir. Apsisi değişse bile ordinat sabit kaldığı için nokta y = 2 doğrusu üzerindedir.'),
  ('A(0, 0), B(4, 0) sabit; APB açısı 90° olacak biçimde P noktası hareket ediyor. P\'nin geometrik yeri nedir?', 'Çapı AB olan çember', ['AB\'nin orta dikmesi', 'A merkezli, yarıçapı 4 olan çember', 'AB doğrusunun paraleli olan iki doğru'], 'Çapı gören çevre açı 90° olduğundan P, çapı AB olan çember üzerindedir: (x − 2)² + y² = 4. A ve B\'de açı tanımsızdır.'),
  ('A(0, 0), B(4, 0) sabit; ABP üçgeninin alanı 6 birimkare olacak biçimde P hareket ediyor. P\'nin geometrik yeri nedir?', 'y = 3 ve y = −3 doğruları', ['Yalnız y = 3 doğrusu', 'x = 3 ve x = −3 doğruları', 'Merkezi orijinde bir çember'], 'Alan = 4·|y|/2 = 6 ise |y| = 3 olur. Nokta iki paralel doğru üzerinde bulunur.'),
  ('Bir noktanın x eksenine uzaklığı, y eksenine uzaklığının iki katıdır. Bu noktaların geometrik yeri nedir?', 'y = 2x ve y = −2x doğruları', ['y = x/2 ve y = −x/2 doğruları', 'Yalnız y = 2x doğrusu', 'Merkezi orijinde bir çember'], '|y| = 2|x| olduğundan y = 2x ya da y = −2x olur.'),
  ('İki radar istasyonu A(0, 0) ve B(10, 0) konumunda (birim km). Bir uçak her iki istasyondan da 13 km uzaklıkta ise uçağın ordinatının mutlak değeri kaç km\'dir?', '12', ['13', '5', '√69'], 'Uçak AB\'nin orta dikmesi üzerindedir: x = 5. 25 + y² = 169 olduğundan |y| = 12\'dir.'),
  ('Bir gözetleme kulesi orijinde olup 5 km yarıçaplı alanı görmektedir. Yol 3x + 4y = 30 doğrusu (km) boyunca uzanıyorsa hangisi doğrudur?', 'Yol, kulenin görüş alanının dışında kalır', ['Yol, görüş alanının sınırına teğet olarak değer', 'Yol, görüş alanını iki noktada keserek geçer', 'Yol, doğrudan kulenin üzerinden geçer'], 'Kuleden yola uzaklık 30/5 = 6 km\'dir ve görüş yarıçapı olan 5 km\'den büyüktür. Yol görüş alanının dışındadır.'),
  ('Üç köy A(0, 0), B(8, 0) ve C(0, 6) noktalarındadır (birim km). Üçüne eşit uzaklıkta kurulacak sağlık ocağı köylerden kaç km uzakta olur?', '5', ['10', '4', '3√2'], 'A\'daki açı dik olduğundan BC çap olur. Merkez (4, 3), yarıçap |BC|/2 = 10/2 = 5 km\'dir.'),
  ('Bir bisikletçi 3x − 4y = 0 doğrusu boyunca ilerliyor. Yardımcı ekip (10, 0) noktasında bekliyorsa bisikletçiye en yakın uzaklık kaç birimdir?', '6', ['8', '5', '7,5'], 'En yakın uzaklık dik uzaklıktır: |30 − 0|/√(9 + 16) = 6.'),
  ('x² + y² ≤ 25 ve x² + y² ≥ 9 eşitsizliklerini birlikte sağlayan bölgenin alanı kaç birimkaredir?', '16π', ['34π', '25π', '64π'], 'Bölge, yarıçapları 5 ve 3 olan eş merkezli çemberler arasındaki halkadır. Alan 25π − 9π = 16π\'dir.'),
  ('x² + y² ≤ 16 ve |y| ≤ x eşitsizlikleri birlikte hangi bölgeyi belirtir ve alanı kaçtır?', '90°\'lik bir daire dilimi, 4π', ['Yarım daire, 8π', '60°\'lik bir daire dilimi, 8π/3', 'Tam daire, 16π'], '|y| ≤ x, y = ±x doğruları arasındaki sağ 90°\'lik açıdır. Daire diliminin alanı 16π/4 = 4π\'dir.'),
  ('x² + y² − 4x ≤ 0 ile verilen dairesel bölgenin yüzölçümü kaçtır?', '4π', ['2π', '16π', '8π'], '(x − 2)² + y² ≤ 4 olur. Bölge yarıçapı 2 olan daredir ve alan 4π\'dir.'),
  ('3x + 4y = 25 doğrusu üzerindeki noktaların orijine uzaklığının karesinin en küçük değeri kaçtır?', '25', ['5', '125', '15'], 'Orijinden doğruya uzaklık 25/5 = 5\'tir ve en küçük uzaklık budur. Kare 25 olur.'),
  ('x² + y² = 25 çemberinin dışındaki P(6, 3) noktasından değme noktası T\'ye çizilen |PT| doğru parçasının boyu nedir?', '2√5', ['√61', '20', '√20 + 1'], 'Kuvvet 36 + 9 − 25 = 20\'dir. Teğet uzunluğu √20 = 2√5\'tir.'),
  ('x² + y² = 25 çemberinin içindeki P(3, 0) noktasından geçen herhangi bir kirişin P ile bölünen iki parçasının uzunlukları çarpımı kaçtır?', '16', ['−16', '25', '34'], 'Noktanın kuvveti 9 − 25 = −16\'dır. Mutlak değeri, P\'den geçen her kirişte parçaların çarpımına eşittir.'),
  ('P(8, 0) noktasından çizilen bir kesen x² + y² = 25 çemberini A ve B noktalarında kesiyor. |PA|·|PB| çarpımı kaçtır?', '39', ['64', '−39', '89'], 'Çarpım, noktanın kuvvetidir: 64 − 25 = 39. Örneğin x ekseni boyunca 3·13 = 39 bulunur.'),
  ('P(4, 0) noktasından x² + y² = 4 çemberine çizilen iki teğet arasındaki açı kaç derecedir?', '60°', ['30°', '90°', '120°'], 'sin(θ/2) = r/|OP| = 2/4 = 1/2 olduğundan θ/2 = 30° ve θ = 60°\'dir.'),
  ('x·y > 0 ve x + y < 0 koşullarını sağlayan (x, y) noktaları analitik düzlemin hangi bölgesinde bulunur?', 'Yalnız III. bölgede', ['Yalnız I. bölgede', 'II. ve IV. bölgelerde', 'I. ve III. bölgelerde'], 'Çarpımın pozitif olması aynı işaretli olmayı gerektirir. Toplam negatif olduğundan ikisi de negatiftir; nokta III. bölgededir.'),
  ('(x − 2)(y + 3) = 0 denklemini sağlayan noktaların kümesi nedir?', 'x = 2 ve y = −3 doğrularının birleşimi', ['Yalnız (2, −3) noktası', 'Merkezi (2, −3) olan bir çember', 'x = −2 ve y = 3 doğrularının birleşimi olan bir şekil'], 'Çarpım sıfırsa çarpanlardan biri sıfırdır: x = 2 ya da y = −3. Bu iki doğru (2, −3) noktasında kesişir.'),
  ('Bir A(0, a) noktası ile B(6, 0) noktası 10 birim aralıklıdır. a\'nın olabilecek değerlerinin çarpımını bulunuz.', '−64', ['64', '−8', '−100'], '36 + a² = 100 olduğundan a = ±8\'dir. Çarpım −64\'tür.'),
  ('A(0, 0), B(3, 4) ve C(6, 8) noktaları için |AB| + |BC| = |AC| olduğu görülüyor. Bundan hangi sonuç çıkar?', 'Üç nokta doğrusaldır ve B, AC\'nin orta noktasıdır', ['A, B, C bir dik üçgen oluşturur ve B\'de dik açı vardır', 'A, B, C bir ikizkenar üçgen oluşturur ve tepe B\'dedir', 'B noktası AC\'nin dışındadır'], 'Uzaklıklar 5, 5 ve 10\'dur. Üçgen eşitsizliğinde eşitlik ancak noktalar doğrusal olduğunda sağlanır; |AB| = |BC| olduğundan B orta noktadır.'),
  ('A(0, 0), B(5, 0) ve C(1, 1) köşeli üçgen açılarına göre hangi türdedir?', 'Geniş açılı', ['Dar açılı', 'Dik açılı', 'Eşkenar ve dar açılı'], 'Kenar kareleri 25, 2 ve 17\'dir. En uzun kenarın karesi diğer ikisinin toplamından (19) büyüktür; C\'de açı geniştir.'),
  ('ABCD dörtgeninin köşeleri A(0, 0), B(5, 0), C(8, 4) ve D(3, 4) ise bu dörtgenin özelliği nedir?', 'Kare olmayan eşkenar dörtgen', ['Dikdörtgen', 'Kare', 'Yamuk'], 'Her kenar 5 birimdir. AB ile BC dik olmadığından (iç çarpım 15) dörtgen kare değil, eşkenar dörtgendir.'),
  ('A(0, 3) ve B(4, 1) noktalarına eşit uzaklıkta olan, x ekseni üzerindeki noktanın koordinatları nedir?', '(1, 0)', ['(2, 0)', '(−1, 0)', '(1/2, 0)'], '(a, 0) için a² + 9 = (a − 4)² + 1 olur. 8a = 8 ve a = 1 bulunur.'),
  ('A(2, −3) ve B(8, 5) noktalarını birleştiren doğru parçasını A\'dan başlayarak 2 : 1 oranında içten bölen noktanın koordinatları nedir?', '(6, 7/3)', ['(4, −1/3)', '(5, 1)', '(14/3, 7/3)'], 'P = A + (2/3)(B − A) = (2 + 4, −3 + 16/3) = (6, 7/3).'),
  ('P(−1, 4) noktası A(−3, −2) ve B noktaları arasındaki doğru parçasını |AP| : |PB| = 1 : 2 oranında bölüyor. B noktası hangisidir?', '(3, 16)', ['(1, 7)', '(−9, −6)', '(0, 10)'], 'P = A + (B − A)/3 olduğundan B = A + 3(P − A) = (−3 + 6, −2 + 18) = (3, 16).'),
  ('A(−2, 5) ve B(6, −1) noktalarını birleştiren doğru parçasını y ekseni hangi ordinatlı noktada keser?', '7/2', ['3', '4', '11/4'], 'y ekseni parçayı A\'dan 2/8 = 1/4 oranında böler (x: −2 → 0). Ordinat 5 − 6/4 = 7/2\'dir.'),
  ('ABC üçgeninde AB ve AC kenarlarının orta noktaları D(1, 1) ve E(5, 4) ise BC kenarının uzunluğu kaçtır?', '10', ['5', '5/2', '√65'], '|DE| = √(16 + 9) = 5\'tir. Orta taban teoremine göre |BC| = 2|DE| = 10\'dur.'),
  ('Köşeleri A(0, 0), B(8, 0), C(6, 4) ve D(2, 4) olan yamuğun yan kenarlarının orta noktalarını birleştiren doğru parçasının uzunluğu kaçtır?', '6', ['5', '7', '5,5'], 'AD\'nin orta noktası (1, 2), BC\'nin orta noktası (7, 2)\'dir. Uzaklık 6\'dır; bu, (8 + 4)/2\'ye eşittir.'),
  ('Bir arazi haritasında A(0, 0), B(6, 0) ve C(0, 8) noktaları üçgen bir parselin köşeleridir. C köşesinden karşı kenarın orta noktasına çizilen doğru parçası kaç birimdir?', '√73', ['5', '√58', '√145'], 'AB\'nin orta noktası (3, 0)\'dır. C\'ye uzaklık √(9 + 64) = √73\'tür.'),
  ('(0, 0), (a, 1), (5, 4) ve (3, b) noktaları bu sırayla bir paralelkenarın köşeleridir. a·b çarpımı kaçtır?', '6', ['12', '8', '−6'], 'Karşılıklı köşelerin koordinat toplamları eşittir: 0 + 5 = a + 3 ve 0 + 4 = 1 + b. Buradan a = 2, b = 3 ve a·b = 6.'),
  ('Köşegen uç noktaları (−3, 0), (3, 0), (0, 4) ve (0, −4) olan dörtgenin çevresi kaç birimdir?', '20', ['24', '28', '10√3'], 'Köşegenler eksenler üzerinde birbirini ortalar ve diktir; dörtgen eşkenar dörtgendir. Kenar √(9 + 16) = 5 olduğundan çevre 20\'dir.'),
  ('Bir kadastro paftasında (−2, 1), (3, −1) ve (1, 4) noktalarıyla sınırlanan üçgen parselin yüzölçümü kaç birimkaredir?', '21/2', ['21', '19/2', '−21/2'], 'Ayakkabı bağı toplamı (2 − 3) + (12 + 1) + (1 + 8) = 21 bulunur. Alan 21/2\'dir.'),
  ('Köşeleri sırasıyla (0, 0), (4, 0), (4, 2), (2, 2), (2, 5) ve (0, 5) olan L biçimli çokgenin alanı kaç birimkaredir?', '14', ['20', '−14', '16'], 'Ayakkabı bağı toplamı 0 + 8 + 4 + 6 + 10 + 0 = 28\'dir. Alan 14\'tür; bir dikdörtgen 4·2 = 8 ile bir dikdörtgen 2·3 = 6\'nın toplamıdır.'),
  ('Parabolün y = x² noktalarından A(1, 1), B(2, 4) ve C(3, 9) için hangisi doğrudur?', 'Doğrusal değildirler; AB ve BC eğimleri farklıdır', ['Doğrusaldırlar, çünkü üçü de aynı eğrinin üzerindedir', 'Doğrusaldırlar, çünkü apsisleri ardışıktır', 'Doğrusal değildirler; ordinatları ardışık değildir'], 'AB\'nin eğimi 3, BC\'nin eğimi 5\'tir. Eğimler eşit olmadığından üç nokta doğrusal değildir.'),
  ('Bir doğru x eksenini (m, 0)\'da, y eksenini (0, n)\'de keser ve (2, 3) noktasından geçer. m = 4 ise n değeri nedir?', '6', ['3', '12', '−6'], 'Doğru x/m + y/n = 1 biçimindedir. (2, 3) için 2/4 + 3/n = 1 olur; 3/n = 1/2 ve n = 6\'dır.'),
  ('Bir koşucunun başlangıç noktasından uzaklığı 2. saniyede 10 m, 6. saniyede 34 m olarak ölçülüyor ve hareket düzgündür. Konum-zaman doğrusunun eğimi koşucunun hangi niceliğini verir ve değeri nedir?', 'Hızını, 6 m/s', ['Hızını, 4 m/s', 'İvmesini, 6 m/s²', 'Aldığı yolu, 24 m'], 'Eğim, konumdaki değişimin zamandaki değişime oranıdır: (34 − 10)/(6 − 2) = 6 m/s, yani hızdır.'),
  ('Bir atölyede 10 adet ürünün üretim maliyeti 450 TL, 30 adetin maliyeti 850 TL\'dir. Maliyet adetle doğrusal değişiyorsa sabit gider kaç TL\'dir?', '250', ['−250', '20', '650'], 'Eğim (850 − 450)/(30 − 10) = 20 TL/adet\'tir. Sabit gider 450 − 10·20 = 250 TL\'dir.'),
  ('A(−3, −4) ve B(3, 8) noktalarından geçen doğru x eksenini hangi apsiste keser?', '−1', ['1', '2', '−1/2'], 'Eğim 12/6 = 2\'dir. y + 4 = 2(x + 3) ise y = 2x + 2\'dir. y = 0 için x = −1 bulunur.'),
  ('Bir mum, yanmaya başladığında boyu 20 cm iken 3 saat sonra 11 cm olmuştur. Boy zamanla doğrusal azalıyorsa 5. saatin sonunda mumun boyu kaç cm olur?', '5', ['6', '5,5', '9'], 'Eğim (11 − 20)/3 = −3 cm/saattir. Boy = 20 − 3t olduğundan t = 5\'te 5 cm\'dir.'),
  ('y = −2x + 8 doğrusunun koordinat eksenleri arasında kalan parçasının uzunluğu kaç birimdir?', '4√5', ['2√5', '12', '4√10'], 'Doğru eksenleri (4, 0) ve (0, 8) noktalarında keser. Parçanın uzunluğu √(16 + 64) = 4√5\'tir.'),
  ('x − 2y + 6 = 0 doğrusunun koordinat eksenleri arasında kalan parçasının orta noktası hangisidir?', '(−3, 3/2)', ['(−3/2, 3/2)', '(−3, 3)', '(−6, 3)'], 'Doğru eksenleri (−6, 0) ve (0, 3) noktalarında keser. Orta nokta (−3, 3/2)\'dir.'),
  ('(a − 2)x + (a + 1)y + 3 = 0 doğrusu x eksenine paralel ise a kaçtır?', '2', ['−1', '3', '−2'], 'x eksenine paralel doğruda x\'in katsayısı sıfır olmalıdır: a − 2 = 0 ve a = 2. Bu durumda y\'nin katsayısı 3 ≠ 0\'dır.'),
  ('A(2, 3) noktasından geçen ve x − 2y + 1 = 0 doğrusuna dik olan doğrunun denklemi hangisidir?', '2x + y − 7 = 0', ['x + 2y − 8 = 0', '4x + 2y − 7 = 0', '2x + y + 7 = 0'], 'Verilen doğrunun eğimi 1/2\'dir; dik doğrunun eğimi −2\'dir. y − 3 = −2(x − 2) ise 2x + y − 7 = 0\'dır.'),
  ('3x + ay = 1 ve (a − 1)x + 2y = 5 doğruları birbirine dik ise a kaçtır?', '3/5', ['5/3', '−3/5', '1'], 'Dik doğrularda a₁a₂ + b₁b₂ = 0\'dır: 3(a − 1) + 2a = 0 ve 5a = 3, a = 3/5.'),
  ('Merkezi y = x + 1 doğrusu üzerinde olan ve O(0, 0) ile A(4, 0) noktalarından geçen çemberin denklemi hangisidir?', '(x − 2)² + (y − 3)² = 13', ['(x − 2)² + (y − 3)² = 169', '(x − 1)² + (y − 2)² = 5', '(x − 3)² + (y − 2)² = 13'], 'OA\'nın orta dikmesi x = 2\'dir. Merkez y = x + 1 üzerinde olduğundan (2, 3) bulunur; r² = 4 + 9 = 13.'),
  ('Merkezi x + y = 4 doğrusu üzerinde olan ve A(0, 0), B(0, 6) noktalarından geçen çemberin yarıçapı kaçtır?', '√10', ['3', '√13', '2√10'], 'Merkez AB\'nin orta dikmesi y = 3 üzerindedir; x + y = 4 ile kesişimi (1, 3)\'tür. r = √(1 + 9) = √10.'),
  ('Bir çemberin merkezi y = 2x doğrusu üzerindedir ve çember x eksenine (2, 0) noktasında değmektedir. Çemberin denklemi nedir?', '(x − 2)² + (y − 4)² = 16', ['(x − 2)² + (y − 1)² = 1', '(x − 2)² + (y − 4)² = 256', '(x − 1)² + (y − 2)² = 4'], 'Teğet noktasında merkezin apsisi 2\'dir. Merkez y = 2x üzerinde olduğundan (2, 4) ve r = 4\'tür.'),
  ('Merkezi (1, 2) olan ve 3x + 4y − 5 = 0 doğrusuna teğet olan çemberin yarıçapının karesi kaçtır?', '36/25', ['6/5', '36/5', '−36/25'], 'Yarıçap merkezin doğruya uzaklığıdır: |3 + 8 − 5|/5 = 6/5. Karesi 36/25\'tir.'),
  ('3x − 4y + 1 = 0 ve 3x − 4y − 9 = 0 paralel doğrularına teğet olan bir çemberin yarıçapı kaç birimdir?', '1', ['2', '5', '10'], 'Doğrular arası uzaklık |1 + 9|/5 = 2\'dir. Çemberin çapı bu uzaklığa eşit olduğundan yarıçap 1\'dir.'),
  ('x² + y² = 50 çemberine içten çizilen, kenarları eksenlere paralel karenin alanı kaç birimkaredir?', '100', ['50√2', '200', '25'], 'Köşeler (±5, ±5) noktalarıdır, çünkü 25 + 25 = 50\'dir. Kenar 10 olduğundan alan 100\'dür.'),
  ('(x − 3)² + (y + 1)² = 25 dairesinin alanını iki eşit parçaya bölen doğru aşağıdakilerden hangisidir?', 'x + y = 2', ['x + y = 3', 'x − y = 2', '2x + y = 4'], 'Alanı yarıya bölen doğru merkezden geçer. (3, −1) yalnız x + y = 2 denklemini sağlar.'),
  ('x² + y² = 16 çemberi üzerindeki bir noktanın A(12, 5) noktasına en kısa uzaklığı kaç birimdir?', '9', ['13', '17', '8'], '|OA| = 13\'tür. En kısa uzaklık 13 − 4 = 9\'dur.'),
  ('x² + y² = 25 ve (x − 8)² + y² = 9 çemberlerinin tek ortak noktası hangisidir?', '(5, 0)', ['(3, 0)', '(4, 0)', '(5/2, 0)'], 'Merkezler arası uzaklık 8 = 5 + 3\'tür; çemberler dıştan teğettir. Değme noktası, birinci çemberin merkezden 5 birim uzaklıktaki (5, 0)\'dır.'),
  ('Orijinden (x − 3)² + y² = 1 çemberine bir teğet çiziliyor. Orijinle değme noktası arasındaki uzaklık nedir?', '2√2', ['√10', '√8 + 1', '8'], 'Orijinin kuvveti 9 − 1 = 8\'dir. Teğet uzunluğu √8 = 2√2\'dir.'),
  ('Bir çemberin denkleminde x ve y\'nin katsayıları eşit ve xy terimi yoksa, ancak merkezin orijinde olduğu bilinmiyorsa genel denklem hangi terimler yoluyla merkezi verir?', 'x ve y\'nin birinci dereceden terimleri', ['Yalnız sabit terim ile x² ve y² katsayılarının oranı', 'x² ve y² terimlerinin katsayıları ile sabit terim', 'xy çarpım terimi ve sabit terim birlikte'], 'Genel denklemdeki Dx ve Ey terimleri merkezi (−D/2, −E/2) olarak belirler. Sabit terim yarıçapı etkiler.'),
  ('O(0, 0), B(4, 0) ve C(0, 3) köşeli üçgenin iç teğet çemberinin merkezi hangisidir?', '(1, 1)', ['(2, 3/2)', '(4/3, 1)', '(1, 3/2)'], 'Dik kenarlar 4 ve 3, hipotenüs 5\'tir. r = (4 + 3 − 5)/2 = 1 olur ve merkez dik köşeden her kenara 1 birim uzaktadır: (1, 1).'),
  ('x ekseni ve y = √3x doğruları arasındaki dar açının açıortayının eğimi kaçtır?', '√3/3', ['√3', '1', '2√3/3'], 'Eğim açıları 0° ve 60°\'dir. Açıortayın eğim açısı 30° olduğundan eğimi tan 30° = √3/3\'tür.'),
  ('Bir ışın A(1, 1) noktasından B(5, 3) noktasına doğru ilerlerken x + y = 4 doğrusunu geçiyor. Geçiş noktası hangisidir?', '(7/3, 5/3)', ['(−7/3, −5/3)', '(2, 2)', '(7/2, 5/2)'], 'A için 1 + 1 − 4 = −2, B için 5 + 3 − 4 = 4 olduğundan doğru parçayı keser. P = (1 + 4t, 1 + 2t) için 2 + 6t = 4 ve t = 1/3 olur.'),
  ('y = −x aynasında 2x + 3y = 6 doğrusunun görüntüsü hangi doğrudur?', '3x + 2y + 6 = 0', ['3x + 2y − 6 = 0', '2x + 3y + 6 = 0', '−3x + 2y + 6 = 0'], 'y = −x\'e göre simetride (x, y) → (−y, −x) olur. 2(−y) + 3(−x) = 6 ise 3x + 2y + 6 = 0\'dır.'),
  ('Kafes noktalarıyla köşeleri belirlenen çokgenlerin alanını iç ve sınır nokta sayılarıyla veren teorem hangi matematikçiye aittir ve hangi yıl yayımlanmıştır?', 'Georg Pick, 1899', ['Carl Gauss, 1801', 'Leonhard Euler, 1750', 'Henri Poincaré, 1905'], 'Pick teoremi A = İ + S/2 − 1, 1899\'da Georg Alexander Pick tarafından yayımlanmıştır.'),
  ('Manhattan (taksi) uzaklığı matematikte hangi normla aynıdır?', 'ℓ¹ normu (mutlak değerler toplamı)', ['ℓ² normu (Öklid normu)', 'ℓ∞ normu (bileşenlerin en büyüğünün mutlak değeri)', 'Frobenius normu'], 'Manhattan uzaklığı |x₁ − x₂| + |y₁ − y₂| olarak tanımlanır; bu, bileşen farklarının mutlak değerlerinin toplamı olan ℓ¹ normudur.'),
  ('Bir öğrenci x² + y² − 4x + 6y = 3 çemberinin yarıçapını √3 olarak buluyor. Hata nedir ve doğru yarıçap kaçtır?', 'Kareye tamamlama yapılmamış; doğru yarıçap 4\'tür', ['Hata yoktur; yarıçap sabit terimin karekökü olan √3\'tür', 'Yarıçap 3 bulunmalıydı', 'Yarıçap 16 bulunmalıydı'], '(x − 2)² + (y + 3)² = 3 + 4 + 9 = 16 olur. Yarıçap √16 = 4\'tür.'),
  ('Bir öğrenci 3x + 4y − 5 = 0 ve 6x + 8y + 10 = 0 doğruları arasındaki uzaklığı |−5 − 10|/5 = 3 buluyor. Doğru yanıt ve hata nedir?', 'Katsayılar eşitlenmemiş; doğru uzaklık 2\'dir', ['Hata yoktur; uzaklık 3\'tür', 'Payda √(36 + 64) yerine 5 alınmalıydı ve uzaklık 3\'tür', 'Sabit terimler toplanmalıydı; uzaklık 1\'dir'], 'İkinci doğru 3x + 4y + 5 = 0 yazılırsa uzaklık |5 − (−5)|/5 = 2 olur. Formül, katsayıları aynı olan denklemlerde uygulanır.'),
  ('Bir öğrenci \'Eğimlerinin toplamı sıfır olan iki doğru diktir\' diyor. Bu savı çürüten karşı örnek hangisidir?', 'y = 2x ve y = −2x doğruları', ['y = 2x ve y = −x/2 doğruları', 'y = x ve y = −x doğruları', 'y = 0 ve x = 0 doğruları'], 'y = 2x ve y = −2x\'in eğimleri toplamı 0\'dır ama çarpımları −4\'tür; dik değillerdir. Diklik koşulu m₁m₂ = −1\'dir.'),
  ('Bir öğrenci iki çemberin ortak kirişini bulmak için denklemlerini taraf tarafa topluyor. Doğru yöntem hangisidir?', 'Denklemleri taraf tarafa çıkarmak', ['Denklemleri taraf tarafa çarpmak', 'Denklemleri toplayıp ikiye bölmek', 'Merkezleri toplayıp yarıçaplara bölmek'], 'İki çember denklemi çıkarıldığında x² ve y² terimleri yok olur; kalan doğrusal denklem ortak kirişi (kuvvet eksenini) verir.'),
  ('Bir öğrenci (a, b) noktasının y = x doğrusuna göre simetriğini (−b, −a) olarak yazıyor. Bu hatayla ilgili hangisi doğrudur?', '(−b, −a) y = −x\'e göre simetriktir; y = x için (b, a) olmalı', ['Doğru yazılmıştır; simetride her iki koordinatın işareti değişir', 'Doğru simetrik (−a, b)\'dir; çünkü apsis işaret değiştirir', 'Doğru simetrik (a, −b)\'dir; çünkü ordinat işaret değiştirir'], 'y = x\'e göre simetride koordinatlar yer değiştirir: (b, a). (−b, −a) ise y = −x doğrusuna göre simetriktir.'),
  ('Bir öğrenci üç noktanın doğrusal olması için üç noktanın ikişerli uzaklık toplamının 0 olması gerektiğini söylüyor. Doğru ifade hangisidir?', 'Oluşan üçgenin alanı 0 olmalıdır', ['İkişerli uzaklıkların tümü eşit olmalıdır', 'İkişerli eğimlerin çarpımı −1 olmalıdır ve uzaklıklar eşit olmalıdır', 'Üç noktanın ağırlık merkezi orijinde olmalıdır ve eğimler eşit olmalıdır'], 'Doğrusal noktalar bir üçgen oluşturmaz; alan sıfırdır. Uzaklık toplamı farklı noktalar için sıfır olamaz.'),
  ('x + 2y = 6 doğrusu üzerindeki noktalardan orijine en yakın olanı hangisidir?', '(6/5, 12/5)', ['(−6/5, −12/5)', '(6, 0)', '(12/5, 6/5)'], 'En yakın nokta orijinden doğruya inen dikmenin ayağıdır: (6/5)·(1, 2) = (6/5, 12/5).'),
  ('(1, 2) noktasından geçen doğruların orijine uzaklığının alabileceği en büyük değer kaçtır?', '√5', ['3√5/2', '1', '5'], 'Uzaklık, orijinden doğruya inen dikmenin boyudur ve (1, 2) noktasına olan uzaklığı aşamaz. En büyük değer |OP| = √5\'tir.'),
  ('mx − y + 2 = 0 doğrusunun orijine uzaklığı 1 birimdir. m\'nin pozitif değeri kaçtır?', '√3', ['√3/3', '2', '√2'], '2/√(m² + 1) = 1 olduğundan m² = 3\'tür. m pozitif olduğundan m = √3\'tür.'),
  ('Köşeleri O(0, 0), A(2, 0) ve B(0, 2) olan üçgenin iç teğet çemberinin yarıçapı kaç birimdir?', '2 − √2', ['1', '√2 − 1', '2√2 − 2'], 'Kenarlar 2, 2 ve 2√2\'dir. r = (2 + 2 − 2√2)/2 = 2 − √2\'dir.'),
  ('Bir çemberin yarıçapı 3\'tür ve P noktası merkezden √2 uzaklıktadır. P\'den geçen en kısa kirişin uzunluğu nedir?', '2√7', ['√28 + 2', '4√2', '2√2'], 'OP = √2\'dir. En kısa kiriş OP\'ye diktir ve 2√(9 − 2) = 2√7 uzunluğundadır.'),
  ('x² + y² = 36 çemberi üzerindeki A(6, 0) ve B(3, 3√3) noktaları arasında kalan küçük yayın uzunluğu kaç birimdir?', '2π', ['3π', '2π/3', '6π'], 'OB doğrusunun eğimi √3 olduğundan merkez açı 60°\'dir. Yay uzunluğu 6·(π/3) = 2π\'dir.'),
  ('3x + 5y = 30 doğrusu üzerinde her iki koordinatı da pozitif tam sayı olan noktaların apsisleri toplamı kaçtır?', '5', ['10', '15', '8'], 'x, 5\'in katı olmalıdır. x = 5 için y = 3 bulunur; x = 10 için y = 0 pozitif değildir. Yalnız (5, 3) vardır; toplam 5\'tir.'),
  ('P(−4, 3) noktasının y = −x aynasındaki görüntüsü ile orijinden aynalanmış görüntüsü arasındaki mesafe nedir?', '7√2', ['7', '14√2', '√2'], 'y = −x\'e göre simetrik (−3, 4), orijine göre simetrik (4, −3) olur. Uzaklık √(49 + 49) = 7√2\'dir.'),
  ('Bir bahçe x ≥ 0, y ≥ 0, x ≤ 3 ve x + y ≤ 4 koşullarıyla sınırlanıyor. Bahçenin yüzölçümü nedir?', '15/2', ['8', '7', '45/4'], 'Bölge x = 0\'dan 3\'e kadar y = 4 − x doğrusunun altındaki yamuktur. Kenarlar 4 ve 1, yükseklik 3: alan (4 + 1)·3/2 = 15/2.'),
  ('|x − 1| + |y| ≤ 2 ile tanımlanan kare biçimli bölgenin yüzölçümü kaçtır?', '8', ['4', '16', '2'], 'Bölge merkezi (1, 0) olan, köşegenleri 4 birim olan bir karedir. Alan 4·4/2 = 8\'dir.'),
  ('x − y > 0 ve x + y < 0 koşullarını birlikte sağlayan noktalar nasıl bir bölgede bulunur?', 'Negatif y eksenini içine alan 90°\'lik bir açının içinde', ['Pozitif x eksenini içine alan 90°\'lik bir açının tam içinde, sınırlar dahil', 'Yalnız III. bölgede', 'Yalnız IV. bölgede'], 'y < x ve y < −x olmalıdır. Bu, y = x ve y = −x doğruları arasında kalan ve aşağı doğru açılan 90°\'lik kama bölgesidir.'),
  ('Köşeleri A(−2, 0), B(0, 5), C(6, 0) ve D(0, −3) olan dörtgenin köşegenleri birbirine dik midir ve alanı kaç birimkaredir?', 'Evet, 32', ['Evet, 40', 'Hayır, 32', 'Hayır, 24'], 'AC x ekseni, BD y ekseni üzerindedir ve dik kesişirler. Alan |AC|·|BD|/2 = 8·8/2 = 32\'dir.'),
  ('İki radar anteni A(0, 0) ve B(8, 0) noktalarında olup ikisinin de menzili 5 km\'dir. Menzil çemberlerinin kesiştiği iki nokta arasındaki uzaklık kaç km\'dir?', '6', ['5', '8', '6√2'], 'Kesişim noktaları AB\'nin orta dikmesi üzerindedir: x = 4. 16 + y² = 25 olduğundan y = ±3 ve uzaklık 6\'dır.'),
  ('x cos α + y sin α = p (p > 0) biçimindeki doğru denkleminde p sayısı neyi gösterir?', 'Orijinin doğruya olan uzaklığını', ['Doğrunun eğimini', 'Doğrunun y eksenini kestiği noktayı', 'Doğrunun x eksenini kestiği noktayı'], 'Normal biçimde katsayıların karelerinin toplamı 1\'dir; bu nedenle p, orijinden doğruya inen dikmenin uzunluğudur.'),
  ('x + y − 7 = 0 doğrusu ayna kabul edilirse A(1, 2) noktası ile görüntüsü arasındaki mesafe nedir?', '4√2', ['2√2', '8', '4'], 'A\'nın doğruya uzaklığı |1 + 2 − 7|/√2 = 2√2\'dir. Simetrik nokta aynı uzaklıkta karşı tarafta olduğundan |AA\'| = 4√2\'dir.'),
  ('A(0, 0) ve B(4, 0) noktaları ile |AC| = 3 ve |BC| = 5 koşullarını sağlayan C noktasından oluşan üçgenin alanı kaç birimkaredir?', '6', ['10', '12', '15/2'], '|AC|² + |AB|² = 9 + 16 = 25 = |BC|² olduğundan A\'da dik açı vardır. Alan 4·3/2 = 6\'dır.'),
  ('y = x + 1 doğrusu üzerinde A(2, 3) noktasına 3√2 birim uzaklıkta iki nokta vardır. Bu iki noktanın apsislerinin toplamı kaçtır?', '4', ['6', '2', '10'], 'Doğru boyunca Δx = ±3 olur (Δx√2 = 3√2). Apsisler 5 ve −1\'dir; toplam 4\'tür.'),
  ('P(t, 2t + 1) noktasının orijine en kısa uzaklığı kaç birimdir?', '√5/5', ['1', '√5', '2√5/5'], 'P, y = 2x + 1 doğrusu üzerindedir. Orijinden doğruya uzaklık 1/√5 = √5/5\'tir.'),
  ('Üç farklı doğrunun bir üçgen oluşturamaması için hangi durum yeterlidir?', 'İkisinin paralel olması ya da üçünün aynı noktadan geçmesi', ['Üçünün de farklı eğimli olması', 'Üçünün de eksenleri farklı noktalarda kesmesi', 'Yalnız ikisinin diklik koşulunu sağlaması'], 'Paralel iki doğru kesişmeyeceği için üçgenin köşesi eksik kalır; üç doğru tek noktada kesişirse köşeler çakışıp üçgen çöker.'),
  ('x² + y² = 16 çemberine eğimi 3/4 olan iki paralel teğet çizilmiştir. Bu iki teğet arasındaki uzaklık kaç birimdir?', '8', ['4', '16', '6'], 'Paralel iki teğet merkezin iki yanında, merkezden r kadar uzakta bulunur. Aralarındaki uzaklık çapa eşit olan 8\'dir.'),
  ('Eksen üzerindeki (0, 5) noktasından, merkezi orijinde ve yarıçapı 3 olan çembere iki teğet çiziliyor. Teğetlerin eğimleri nedir?', '4/3 ve −4/3', ['3/4 ve −3/4', '16/9 ve −16/9', '4/5 ve −4/5'], 'y = mx + 5 için merkezden uzaklık 5/√(m² + 1) = 3 olmalıdır. m² = 16/9 ve m = ±4/3 bulunur.'),
  ('Alanı 25π olan bir çemberin merkezi birinci bölgede ve y = 2x doğrusu üzerindedir. Çember x eksenine teğet ise merkezin apsisi kaçtır?', '5/2', ['5', '10', '25/4'], 'Teğet çemberde merkezin ordinatı r = 5\'tir. Merkez (a, 2a) olduğundan 2a = 5 ve a = 5/2\'dir.'),
  ('(x − 4)² + (y − 5)² = 9 çemberi için hangisi doğrudur?', 'Koordinat eksenlerini hiçbir noktada kesmez', ['x eksenine teğettir ve y eksenini iki noktada keser', 'y eksenine teğettir ve x eksenini iki noktada keser', 'Her iki ekseni de ikişer noktada keser ve orijinden geçer'], 'Merkezin eksenlere uzaklıkları 5 ve 4\'tür; ikisi de r = 3\'ten büyüktür. Çember eksenlere ulaşmaz.'),
  ('(x − 3)² + (y − 4)² = 25 çemberi koordinat eksenlerini toplam kaç farklı noktada keser?', '3', ['2', '4', '1'], 'x ekseni (0, 0) ve (6, 0)\'da, y ekseni (0, 0) ve (0, 8)\'de kesilir. Orijin ortak olduğundan farklı nokta sayısı 3\'tür.'),
  ('Bir d doğrusuna, doğru üzerindeki P noktasında teğet olan kaç farklı çember vardır?', 'Sonsuz sayıda; merkezleri P\'den d\'ye çizilen dikme üzerindedir', ['Yalnız bir tane; yarıçapı P\'nin doğruya olan uzaklığına eşit olan çember', 'Tam olarak iki tane', 'Hiç yoktur'], 'Merkez, P\'den çıkan dik doğru üzerinde herhangi bir nokta olabilir (P hariç). Her merkez farklı yarıçaplı bir çember verir.'),
  ('Normal formda yazılmamış ax + by + c = 0 doğrusunun noktaya uzaklığı formülünde paydada √(a² + b²) bulunmasının nedeni nedir?', 'Denklemi, normal vektörü birim uzunlukta olan biçime getirmek', ['Doğrunun eğimini ve eksen kesimlerini aynı anda sadeleştirmek için', 'Noktanın orijine uzaklığını eklemek', 'Çözümün her zaman pozitif çıkmasını sağlamak'], 'Denklem √(a² + b²)\'ye bölünürse normal vektör birim olur. Bu durumda payın değeri doğrudan uzaklığı verir.'),
  ('Eğimleri m₁ ve m₂ olan iki doğru için m₁m₂ = −1 ise tan θ = |(m₂ − m₁)/(1 + m₁m₂)| ifadesi nasıl yorumlanır?', 'Payda sıfır olur; tanjant tanımsızdır ve açı 90°\'dir', ['Pay sıfır olur ve doğrular çakışık olduğundan açı 0°\'dir', 'Sonuç 1 olur ve açı 45°\'dir', 'Sonuç −1 olur ve açı 135°\'dir'], '1 + m₁m₂ = 0 olduğundan tanjant tanımsızdır. Bu, doğrular arasındaki açının 90° olduğunu gösterir.'),
  ('A(0, 0), B(6, 0) ve C(0, 6) köşeli üçgenin ağırlık merkezinin hipotenüs doğrusuna uzaklığı kaç birimdir?', '√2', ['2', '2√2', '√2/2'], 'G(2, 2)\'dir. Hipotenüs x + y = 6 doğrusudur; uzaklık |2 + 2 − 6|/√2 = √2\'dir.'),
  ('Bir eşkenar dörtgenin köşeleri A(0, 0), B(4, 3), C(8, 0) ve D(4, −3) noktalarıdır. Bu dörtgenin yüzölçümü nedir?', '24', ['−24', '48', '30'], 'Kenarlar 5\'tir; köşegenler |AC| = 8 ve |BD| = 6\'dır ve birbirine diktir. Alan 8·6/2 = 24\'tür.'),
  ('Simetri merkezi M(3, −1) olan bir dönüşümde P(a, b) noktasının görüntüsü (−1, 5) ise P hangi noktadır?', '(7, −7)', ['(−7/2, 7/2)', '(2, 2)', '(5, −3)'], 'M, P ve simetriğinin orta noktasıdır. a = 6 + 1 = 7 ve b = −2 − 5 = −7 bulunur.'),
  ('(−1, 2) noktasından geçen ve koordinat eksenleri arasında kalan parçası bu nokta tarafından ikiye bölünen doğrunun denklemi hangisidir?', '2x − y + 4 = 0', ['2x + y = 0', 'x − 2y + 5 = 0', '2x − 2y + 4 = 0'], '(−1, 2), eksen kesim noktalarının orta noktasıdır; kesimler (−2, 0) ve (0, 4)\'tür. Doğru x/(−2) + y/4 = 1, yani 2x − y + 4 = 0\'dır.'),
  ('Kenar uzunluğu 6 olan bir eşkenar üçgenin köşeleri A(0, 0), B(6, 0) ve C(3, 3√3)\'tür. İç teğet çemberin yarıçapı nedir?', '√3', ['3√3', '3', '3√3/2'], 'Üçgen eşkenardır; yükseklik 3√3\'tür. İç teğet çemberin yarıçapı yüksekliğin üçte biri olan √3\'tür.'),
  ('Orijinden geçtiği hâlde y = mx biçiminde yazılamayan doğru hangisidir?', 'x = 0 doğrusu (y ekseni)', ['y = 0 doğrusu (x ekseni, yatay)', 'y = x doğrusu', 'y = −x doğrusu'], 'y ekseni düşeydir ve eğimi tanımsızdır; bu yüzden y = mx biçimine uymaz.'),
  ('y = 2x − 3 doğrusu hangi bölgelerden geçer?', 'I., III. ve IV. bölgelerden', ['I., II. ve III. bölgelerden', 'II., III. ve IV. bölgelerden', 'I., II. ve IV. bölgelerden'], 'Doğru eksenleri (3/2, 0) ve (0, −3) noktalarında keser; eğim pozitiftir. Sol alttan sağ üste ilerleyerek III., IV. ve I. bölgeden geçer.'),
  ('Orijinden geçmeyen ve eksenlere paralel olmayan bir doğru en fazla kaç bölgeden geçer?', '3', ['2', '4', '1'], 'Böyle bir doğru iki ekseni farklı noktalarda keser ve tam olarak üç bölgeden geçer; geçmediği bölge eksen kesimlerinin işaretlerine göre belirlenir.'),
  ('Çevre ve alandan yararlanarak, köşeleri A(−3, 0), B(3, 0) ve C(0, 4) olan ikizkenar üçgenin içine çizilebilen en büyük çemberin yarıçapını bulunuz.', '3/2', ['1', '2', '12/5'], 'Kenarlar 5, 5 ve 6\'dır; çevrenin yarısı 8, alan 12\'dir. r = 12/8 = 3/2\'dir.'),
  ('x² + y² = 4 ve (x − 2)² + (y − 2)² = 4 çemberlerinin ortak kirişinin uzunluğu kaç birimdir?', '2√2', ['2√2 − 2', '√2', '2√3'], 'Denklemler çıkarılırsa x + y = 2 bulunur. Orijinden doğruya uzaklık √2\'dir; kiriş 2√(4 − 2) = 2√2\'dir.'),
  ('Orijin merkezli, yarıçapı 3 olan çembere P noktasından çizilen iki teğet birbirine diktir. P noktasının orijine uzaklığı kaç birimdir?', '3√2', ['9√2/2', '3', '3√3'], 'Teğetler arası açı 90° ise OAPB bir karedir (A, B değme noktaları). |OP| = r√2 = 3√2\'dir.'),
  ('AB = (3, 1) ve AD = (1, 4) vektörleriyle kurulan ABCD paralelkenarının yüzölçümü nedir?', '11', ['13', '12', '11,5'], 'AB = (3, 1) ve AD = (1, 4) vektörleri için alan |3·4 − 1·1| = 11\'dir.'),
  ('Bir doğru parçasının uçları A(−3, −2) ve B(5, 4)\'tür. Bu parçanın orta dikmesi y eksenini hangi ordinatta keser?', '7/3', ['4/3', '−7/3', '11/3'], 'Orta nokta (1, 1), AB eğimi 3/4 olduğundan orta dikmenin eğimi −4/3\'tür. y − 1 = −4(x − 1)/3 ve x = 0 için y = 7/3\'tür.'),
  ('A(1, 3) ve B(−3, 1) noktalarına eşit uzaklıkta bulunan noktaların oluşturduğu doğrunun denklemi nedir?', 'y = −2x', ['y = 2x + 5', 'y = −2x + 3', 'y = x/2 + 5/2'], 'Orta nokta (−1, 2), AB eğimi 1/2\'dir. Orta dikmenin eğimi −2\'dir: y − 2 = −2(x + 1), yani y = −2x.'),
  ('3x − 4y + k = 0 doğrusu P(1, 2) noktasından 1 birim uzaktadır. k değerlerinin toplamı nedir?', '10', ['0', '5', '−10'], '|3 − 8 + k|/5 = 1 olduğundan |k − 5| = 5 ve k = 0 ya da k = 10\'dur. Toplam 10\'dur.'),
  ('A(0, 6) noktasının x + y − 2 = 0 doğrusu üzerindeki dik iz düşümü hangi noktadır?', '(−2, 4)', ['(1, 1)', '(−4, 6)', '(−1/2, 13/2)'], 'İfade değeri 4\'tür. Dik iz düşüm A − (4/2)·(1, 1) = (−2, 4)\'tür.'),
  ('y = x + k doğrusu x² + y² = 4 çemberine değiyorsa k\'nın alabileceği iki değerin çarpımını bulunuz.', '−8', ['8', '−4', '−16'], 'Merkezin doğruya uzaklığı |k|/√2 = 2 olmalıdır. k = ±2√2 ve çarpım −8\'dir.'),
  ('x² + y² = 25 çemberi ile y = −x + 7 doğrusunun kesiştiği iki nokta arasındaki uzaklık kaç birimdir?', '√2', ['2', '5√2/2', '1'], 'Denklem x² − 7x + 12 = 0 verir ve noktalar (3, 4), (4, 3)\'tür. Aralarındaki uzaklık √2\'dir.'),
  ('t ∈ [0, π] için (3cos t, 3sin t) noktalarının oluşturduğu yol nasıl bir şekil çizer?', 'Merkezi orijinde olan çemberin üst yarısını', ['Merkezi orijinde olan tam çemberi', 'Merkezi orijinde olan çemberin sağ yarısını ve ekseni', 'Çember ile içindeki karenin birleşimini'], 'x² + y² = 9\'dur ve t ∈ [0, π] için y = 3 sin t ≥ 0 olduğundan yalnız çemberin üst yarısı elde edilir.'),
  ('(1 + t, 2 − 2t) noktaları t gerçek sayı olmak üzere bir doğru çizer. Bu doğrunun iki koordinat ekseni arasında kalan parçası kaç birim uzunluğundadır?', '2√5', ['√5', '√20 + 1', '2√2'], 'y = 0 için t = 1 ve nokta (2, 0); x = 0 için t = −1 ve nokta (0, 4) bulunur. Uzunluk √(4 + 16) = 2√5\'tir.'),
  ('Köşeleri (±3, 0) ve (0, ±3) olan kare bölgenin içinde ve sınırında kaç kafes noktası bulunur?', '25', ['29', '13', '21'], '|x| + |y| = k için 4k nokta vardır (k ≥ 1). Toplam 1 + 4 + 8 + 12 = 25\'tir.'),
  ('|x| + |y| ≤ 4 koşuluyla belirlenen kare bölgeye içten teğet olan çemberin yarıçapı kaç birimdir?', '2√2', ['√2 + 2', '√2', '2'], 'Karenin köşegeni 8, kenarı 4√2\'dir. İçten teğet çemberin yarıçapı kenarın yarısı olan 2√2\'dir.'),
  ('A(1, 1) ve B(7, 1) köşeli ABC üçgeninin C köşesi y = 5 doğrusu üzerinde hareket ediyor. Üçgenin alanı için hangisi doğrudur?', 'C nerede olursa olsun alan 12 birimkaredir', ['C\'nin apsisi büyüdükçe alan artar', 'C ordinatı 5 olduğundan alan 5 birimkaredir', 'Alan C\'nin konumuna göre 6 ile 24 arasında değişir'], 'Taban AB = 6 sabittir ve C\'nin AB\'ye uzaklığı 4\'tür. Alan 6·4/2 = 12 olarak sabit kalır.'),
];
